-- QQ幻想私服开发期唯一初始化脚本。
--
-- 本文件是数据库 schema 与静态业务数据的唯一真相源，只允许在空数据库执行。
-- 小改动：对现有开发库执行精确的增量 SQL，并同步修改本文件。
-- 大改动：先 pg_dump，再删除并重建数据库，执行本文件，最后恢复玩家数据。
-- 服务端运行时只从 PostgreSQL 读取业务数据，不读取仓库内 JSON 配置。



-- ===== folded from 0001_init.sql =====

-- QQ幻想私服 · 初始 schema (A0.5 持久化落地)
-- 设计对应 domain 层模型(见 internal/domain)。约束在 DB 层强制, 保证不丢档/不重名。

-- 账号
CREATE TABLE IF NOT EXISTS accounts (
    id         BIGSERIAL PRIMARY KEY,
    username   TEXT        NOT NULL UNIQUE,
    pass_hash  TEXT        NOT NULL DEFAULT '',   -- bcrypt/argon2, 明文永不落库
    sec_hash   TEXT        NOT NULL DEFAULT '',   -- 安全码同样只保存哈希
    banned     BOOLEAN     NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- 角色
CREATE TABLE IF NOT EXISTS characters (
    id          BIGSERIAL PRIMARY KEY,
    account_id  BIGINT      NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    slot        INT         NOT NULL,
    name        TEXT        NOT NULL UNIQUE,       -- 全服唯一角色名
    race        SMALLINT    NOT NULL,
    level       INT         NOT NULL DEFAULT 1,
    exp         BIGINT      NOT NULL DEFAULT 0,
    map_id      INT         NOT NULL,
    pos_x       DOUBLE PRECISION NOT NULL,
    pos_y       DOUBLE PRECISION NOT NULL,
    scene_instance BIGINT   NOT NULL DEFAULT 0 CHECK (scene_instance BETWEEN 0 AND 4294967295),
    gender      SMALLINT    NOT NULL DEFAULT 0,
    hair        SMALLINT    NOT NULL DEFAULT 0,
    face        SMALLINT    NOT NULL DEFAULT 0,
    equip_view  BYTEA       NOT NULL DEFAULT '',   -- 装备外观槽(U16×6), A5 结构化前作为字节
    stat_blob   BYTEA       NOT NULL DEFAULT '',   -- 属性块(A3 结构化前不透明保留)
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    last_login  TIMESTAMPTZ NOT NULL DEFAULT now(),
    -- 同账号同槽位唯一
    UNIQUE (account_id, slot)
);

CREATE INDEX IF NOT EXISTS idx_characters_account ON characters(account_id);

-- ===== folded from 0002_gamedata.sql =====

-- QQ幻想私服 · 游戏静态数据 schema (G2)
--
-- 数据来源：游戏客户端提供的原版数据表。
-- 这些是**静态内容数据**(地图/NPC/怪物/物品/技能...), 与玩家存档(0001_init)分离:
--   - 静态数据可由解包重新生成, 导入器幂等; 玩家数据不可再生。
--   - 全部只读, 服务端启动时载入内存/按需查询。
--
-- 设计要点(诚实处理"字段未完全解出"):
--   精确解出的列建成正式字段; 每张 ov 表的整条原始记录同时以 raw BYTEA 保留 ——
--   不丢任何信息, 后续解出更多字段时可就地补列, 无需重新解包。

-- ── 地图 ──────────────────────────────────────────────────────────────────
-- 来源: 客户端 MapDef.byId(内存读出) -> assets/client/mapdef_table.json
CREATE TABLE IF NOT EXISTS map_defs (
    id       INT  PRIMARY KEY,          -- 地图数字 id(协议里用这个, 如 7=龙城)
    file     TEXT NOT NULL,             -- 资源文件名(qw0007), 对应 map/<file>.npc 等
    name     TEXT NOT NULL,             -- 中文名(龙城)
    is_city  BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE INDEX IF NOT EXISTS idx_map_defs_file ON map_defs(file);

-- 来源: 客户端 map.def 的 ReviveMap 与 RevivePos 第一组坐标。
-- 固定选择原始第一个有效落点是本服规则；死亡回城、回城卷轴与回城书共用。
-- 使用静态地图号，幻想小岛 21000 ↔ 协议号 60 由装配层翻译。
CREATE TABLE IF NOT EXISTS game_map_returns (
    map_id     INT PRIMARY KEY DEFAULT 0 REFERENCES map_defs(id) CHECK (map_id > 0),
    to_map_id  INT NOT NULL DEFAULT 0 REFERENCES map_defs(id) CHECK (to_map_id > 0),
    x          INT NOT NULL DEFAULT 0 CHECK (x >= 0),
    y          INT NOT NULL DEFAULT 0 CHECK (y >= 0)
);

-- 第一版副本定义。来源: 客户端 map/pworld.def；生产运行时只读本表，
-- 不再从客户端目录加载 INI/JSON 业务配置。
CREATE TABLE IF NOT EXISTS game_dungeons (
    map_id         INT  PRIMARY KEY DEFAULT 0 REFERENCES map_defs(id),
    dungeon_id     INT  NOT NULL DEFAULT 0 CHECK (dungeon_id > 0),
    name           TEXT NOT NULL DEFAULT '' CHECK (name <> ''),
    enter_x        INT  NOT NULL DEFAULT 0 CHECK (enter_x >= 0),
    enter_y        INT  NOT NULL DEFAULT 0 CHECK (enter_y >= 0),
    exit_map_id    INT  NOT NULL DEFAULT 0 REFERENCES map_defs(id),
    exit_x         INT  NOT NULL DEFAULT 0 CHECK (exit_x >= 0),
    exit_y         INT  NOT NULL DEFAULT 0 CHECK (exit_y >= 0),
    timeout_sec    INT  NOT NULL DEFAULT 0 CHECK (timeout_sec >= 0),
    max_instances  INT  NOT NULL DEFAULT 0 CHECK (max_instances >= 0),
    solo           BOOLEAN NOT NULL DEFAULT FALSE
);

-- 每图 NPC。来源: map/<file>.npc(gbk ini 明文)
CREATE TABLE IF NOT EXISTS map_npcs (
    map_file  TEXT NOT NULL,            -- qw0007
    npc_id    INT  NOT NULL,            -- 图内编号
    sprite    INT  NOT NULL,            -- Index, 模型号(-> npc<Index>)
    name      TEXT NOT NULL,
    script    TEXT NOT NULL DEFAULT '', -- 交互脚本名(N601FY)
    x         INT  NOT NULL,
    y         INT  NOT NULL,
    dir       INT  NOT NULL DEFAULT 0,
    sell_list INT  NOT NULL DEFAULT 0,  -- 商店 id(0=不卖东西)
    trans_list INT NOT NULL DEFAULT 0,  -- 传送表 id
    portrait  TEXT NOT NULL DEFAULT '', -- 已核实的 res/dlgpic/<name>.gsa 立绘名
    hide      BOOLEAN NOT NULL DEFAULT FALSE,
    PRIMARY KEY (map_file, npc_id)
);
CREATE INDEX IF NOT EXISTS idx_map_npcs_map ON map_npcs(map_file);

-- NPC 飞空艇传送菜单。列表号来自 map_npcs.trans_list；索引与正式客户端
-- TransportUI.sel 一致为零基。货币面额进率尚未闭合，当前航线明确配置为免费。
CREATE TABLE IF NOT EXISTS game_transport_destinations (
    trans_list        INT  NOT NULL,
    destination_index INT NOT NULL CHECK (destination_index >= 0),
    source_map_id     INT  NOT NULL REFERENCES map_defs(id),
    name              TEXT NOT NULL CHECK (name <> ''),
    map_id            INT  NOT NULL REFERENCES map_defs(id),
    x                 INT  NOT NULL CHECK (x >= 0),
    y                 INT  NOT NULL CHECK (y >= 0),
    price             INT  NOT NULL DEFAULT 0 CHECK (price = 0),
    is_dungeon        BOOLEAN NOT NULL DEFAULT FALSE,
    require_clear     BOOLEAN NOT NULL DEFAULT FALSE,
    PRIMARY KEY (trans_list, destination_index),
    UNIQUE (trans_list, map_id),
    CHECK (source_map_id <> map_id)
);
CREATE INDEX IF NOT EXISTS idx_transport_source_map ON game_transport_destinations(source_map_id);

-- 每图怪物刷新点。来源: map/<file>.lst
CREATE TABLE IF NOT EXISTS map_monster_spawns (
    map_file  TEXT NOT NULL,
    spawn_id  INT  NOT NULL,            -- 图内刷新点编号
    monster   INT  NOT NULL,            -- index, 对应 game_monsters.id
    x         INT  NOT NULL,
    y         INT  NOT NULL,
    dir       INT  NOT NULL DEFAULT 0,
    PRIMARY KEY (map_file, spawn_id)
);
CREATE INDEX IF NOT EXISTS idx_spawns_map ON map_monster_spawns(map_file);
CREATE INDEX IF NOT EXISTS idx_spawns_monster ON map_monster_spawns(monster);

-- 传送门。来源: map/<file>.link
CREATE TABLE IF NOT EXISTS map_teleports (
    map_file  TEXT NOT NULL,
    proc_id   INT  NOT NULL,            -- 对应 .prc 区域编号(踩到该区域触发)
    map_to    INT  NOT NULL,            -- 目标地图 id
    to_x      INT  NOT NULL,
    to_y      INT  NOT NULL,
    to_dir    INT  NOT NULL DEFAULT 0,
    back_x    INT  NOT NULL DEFAULT 0,  -- 返回点(反向传送用)
    back_y    INT  NOT NULL DEFAULT 0,
    back_dir  INT  NOT NULL DEFAULT 0,
    script    TEXT NOT NULL DEFAULT '', -- map_script；已闭合的脚本门由服务端显式解释
    PRIMARY KEY (map_file, proc_id)
);
CREATE INDEX IF NOT EXISTS idx_teleports_map ON map_teleports(map_file);

-- ── 内容表(ov_*.bin 精确解出的部分) ─────────────────────────────────────────
CREATE TABLE IF NOT EXISTS game_items (
    id   INT  PRIMARY KEY,              -- 3001 肉片
    name TEXT NOT NULL,
    raw  BYTEA NOT NULL                 -- 整条原始记录(233B), 未解字段留待细化
);

CREATE TABLE IF NOT EXISTS game_equipment (
    id   INT  PRIMARY KEY,              -- 1001 铁剑
    name TEXT NOT NULL,
    raw  BYTEA NOT NULL                 -- 338B
);

-- 少量客户端物品定义的 avatar 与正式客户端实际资源身份相反时，只在业务配置层
-- 覆盖外观，不改写无损导入的 gamedata 原表。工作服四件由真机穿戴确认成对互换：
-- 950/951 是渔夫男女，952/953 是矿工男女。
CREATE TABLE IF NOT EXISTS game_equipment_appearance_overrides (
    item_id INT  PRIMARY KEY REFERENCES game_equipment(id) ON DELETE CASCADE,
    avatar  TEXT NOT NULL CHECK (avatar <> ''),
    reason  TEXT NOT NULL DEFAULT ''
);

CREATE TABLE IF NOT EXISTS game_monsters (
    id     INT  PRIMARY KEY,            -- 1001 树妖
    sprite INT  NOT NULL,               -- 模型号
    name   TEXT NOT NULL,
    raw    BYTEA NOT NULL               -- 76B
);

-- 等级经验表(12×int32/行, 已解出且单调递增)
CREATE TABLE IF NOT EXISTS game_levels (
    level      INT PRIMARY KEY,
    exp        BIGINT NOT NULL,         -- 本级经验值(单调递增)
    exp_accum  BIGINT NOT NULL,         -- 累计
    raw        BYTEA  NOT NULL          -- 48B, 其余列语义待定
);

-- ── 全量兜底: 139 张 ov 表的每一行都无损入库 ───────────────────────────────
-- 精确列尚未解出的表(宠物/帮派/精炼/镶嵌/副本…)先整条保留, 保证"解包出的数据一条不丢"。
-- 解出结构后可从这里就地生成正式表, 不必重新解包。
CREATE TABLE IF NOT EXISTS ov_rows (
    tbl     TEXT   NOT NULL,            -- ov_item.bin
    row_no  INT    NOT NULL,            -- 行号(0起)
    first_i INT,                        -- 首列 int32(多数表是 id), 便于查
    raw     BYTEA  NOT NULL,
    PRIMARY KEY (tbl, row_no)
);
CREATE INDEX IF NOT EXISTS idx_ov_rows_first ON ov_rows(tbl, first_i);

-- 表元信息(记录大小/行数/来源), 供导入器与排查用
CREATE TABLE IF NOT EXISTS ov_tables (
    tbl         TEXT PRIMARY KEY,
    record_size INT  NOT NULL,
    row_count   INT  NOT NULL,
    imported_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ===== folded from 0003_gamedata_stats.sql =====

-- 补列: 已交叉验证解出的数值字段(G1 深度解析)
--
-- 字段说明:
--   ov_arm  +107 u32 = 价格   (铁剑500/钢剑4730/辉石剑14840/妖泣101700; 9048/9089 非零)
--   ov_arm  +115 u8  = 等级需求(铁剑1/钢剑6/辉石剑12/妖泣30; 8692/9089 非零, 96% 落在 1..150)
--   ov_item +82  u32 = 价格   (肉片30/牛肉面105/豆奶50/果酒125; 12253/12541 非零)
--
-- 尚未解出: 装备的攻击/防御等属性 —— 实测不是随等级递增的简单标量
-- (相关性分析无强相关字段; 疑似以"(属性类型,值)对列表"打包在记录中)。
-- 这些仍完整保留在 raw 列, 解出后同样以本文件的方式补列。

ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS price     BIGINT NOT NULL DEFAULT 0;
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS level_req INT    NOT NULL DEFAULT 0;
ALTER TABLE game_items     ADD COLUMN IF NOT EXISTS price     BIGINT NOT NULL DEFAULT 0;

CREATE INDEX IF NOT EXISTS idx_equipment_level ON game_equipment(level_req);

-- ===== folded from 0004_ov_named.sql =====

-- 通用内容名字表(G1 深化): 55 张 ov 表都定位到了 (id列, 名字列),
-- 于是全部内容(技能/任务/对话/提示/宠物/徽章…)都能按名字查, 不必等每张表逐一解出完整结构。
-- 字段名称与客户端表定义一致；部分字段依据记录布局辨认。
CREATE TABLE IF NOT EXISTS ov_named (
    tbl     TEXT NOT NULL,          -- ov_skilldesc.bin
    row_no  INT  NOT NULL,
    ref_id  INT  NOT NULL,          -- 该行的 id 列
    name    TEXT NOT NULL,          -- 该行的名字/文本列
    PRIMARY KEY (tbl, row_no)
);
CREATE INDEX IF NOT EXISTS idx_ov_named_id   ON ov_named(tbl, ref_id);
CREATE INDEX IF NOT EXISTS idx_ov_named_name ON ov_named(name);

-- ===== folded from 0005_teleport_poly.sql =====

-- 传送门触发区(多边形)。
-- 两个数据源互补, 合并后才完整:
--   .link 解包文件      447 图 / 995 门, 有 proc_id→目标图/落点, **无多边形**
--   teleport_links.json 430 图 / 891 门(客户端 Unity 资源), **全部含多边形**, 但少 17 图
-- 关联键: json 里 gate 的顺序 == .link 的 proc_id 顺序, 且 (mapTo,toX,toY) 逐一吻合(已验证)。
-- 无多边形的 17 张图, 需要时再从 .prc(QQF\x1aPROC 二进制)补。
ALTER TABLE map_teleports ADD COLUMN IF NOT EXISTS poly INT[];

-- ===== folded from 0006_equip_stats.sql =====

-- 装备战斗属性(重大修正: 之前误判"装备无属性")。
-- 真实结构: 属性是**从 +79 开始的 u16 槽数组**, 每槽固定对应一种属性。
--   槽0=最小攻击 槽1=最大攻击(武器 100% 覆盖, 且 槽0<=槽1 在 823/823 成立)
--   槽3=防御(防具 91% 覆盖)  槽11=耐久/重量  槽14+15=价格(u32)  槽18=等级需求
-- 早期误判三因: ①用 u8 读截断了 >255 的值 ②拿全表 9089 件当分母(大部分是时装)
--              ③防御找错偏移(在槽3=+85, 不是 +117)
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS atk_min INT NOT NULL DEFAULT 0;
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS atk_max INT NOT NULL DEFAULT 0;
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS defense INT NOT NULL DEFAULT 0;
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS durable INT NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS idx_equip_atk ON game_equipment(atk_max);
CREATE INDEX IF NOT EXISTS idx_equip_def ON game_equipment(defense);

-- ===== folded from 0007_item_desc.sql =====

-- 物品/装备描述(ov_desc.bin, 21630 条)。
-- 结构: id / 名字 / 资源名 / 描述文本。**描述里含真实数值效果**, 是物品效果的权威来源:
--   (小)生命药水 -> "5秒内恢复生命725"   月饼 -> "攻击力提升到300%, 持续五分钟"
--   春笋 -> "5秒内恢复生命1175点"        龙神凭体仙丹 -> "提升生命值上限5000点, 持续15分钟"
-- 后续做物品使用效果时, 从这里正则解析数值(比自行设计更贴原版)。
CREATE TABLE IF NOT EXISTS game_descs (
    id     INT  NOT NULL,
    row_no INT  NOT NULL,
    name   TEXT NOT NULL,
    res    TEXT NOT NULL DEFAULT '',
    text   TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (row_no)
);
CREATE INDEX IF NOT EXISTS idx_descs_id   ON game_descs(id);
CREATE INDEX IF NOT EXISTS idx_descs_name ON game_descs(name);

-- ===== folded from 0008_equip_attrs.sql =====

-- 装备完整属性(用官方资料站 71 件武器逐件对照确认, 8 项命中率 100%)。
-- 来源: fo.qq.com/web200604/information/item03.htm(存档 research/official/)
--   铁剑 攻击1~9 命中5 重量25 力量4 敏捷4  <->  +79/+81/+91/+101/+117/+121 完全吻合
-- 偏移: 79最小攻击 81最大攻击 85防御 87魔法攻击 89魔法防御 91命中 101重量
--       115等级需求 117力量 119体质(推测) 121敏捷 123智慧 125灵巧 68部位 72档次
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS slot       INT NOT NULL DEFAULT 0;
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS tier       INT NOT NULL DEFAULT 0;
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS magic_atk  INT NOT NULL DEFAULT 0;
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS magic_def  INT NOT NULL DEFAULT 0;
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS hit        INT NOT NULL DEFAULT 0;
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS weight     INT NOT NULL DEFAULT 0;
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS strength   INT NOT NULL DEFAULT 0;
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS vitality   INT NOT NULL DEFAULT 0;
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS agility    INT NOT NULL DEFAULT 0;
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS wisdom     INT NOT NULL DEFAULT 0;
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS dexterity  INT NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS idx_equip_slot ON game_equipment(slot);

-- ===== folded from 0009_equip_spirit.sql =====

-- 补最后两项属性: 体力(+119) 与 精神(+213), 均经官方对照 100% 命中。
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS spirit INT NOT NULL DEFAULT 0;
COMMENT ON COLUMN game_equipment.durable IS '重量(+101), 非耐久';

-- ===== folded from 0010_drops_items.sql =====

-- 掉落关系 + 物品等级(来自腾讯官方 2006 资料站, 经 r.jina.ai 抓取, 存档 research/official/)
-- 掉落: 155 条"收集品 <- 怪物"关系, 补上客户端数据里缺失的怪物掉落信息
-- 物品等级: ov_item +76 = 等级/品阶, 官方对照 39/39 = 100%
CREATE TABLE IF NOT EXISTS game_drops (
    item_name    TEXT NOT NULL,
    monster_name TEXT NOT NULL,
    item_id      INT,          -- 关联 game_items.id(按名匹配, 可能为空)
    monster_id   INT,          -- 关联 game_monsters.id
    source       TEXT NOT NULL DEFAULT 'official_2006',
    PRIMARY KEY (item_name, monster_name)
);
CREATE INDEX IF NOT EXISTS idx_drops_monster ON game_drops(monster_id);
ALTER TABLE game_items ADD COLUMN IF NOT EXISTS level INT NOT NULL DEFAULT 0;

-- ===== folded from 0011_monster_official.sql =====

-- 怪物官方资料(腾讯 2007 版资料中心 怪物图鉴, 经 r.jina.ai 抓取)
-- 补上客户端 ov_cmon 缺失的: 怪物等级 / 出没地图 / 掉落物品
-- 132 只怪物(等级 1~50), 127 只按名匹配到 game_monsters
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS level INT NOT NULL DEFAULT 0;
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS maps  TEXT NOT NULL DEFAULT '';
CREATE INDEX IF NOT EXISTS idx_monsters_level ON game_monsters(level);

-- ===== folded from 0012_equip_req.sql =====

-- 语义修正 + 新字段(2007版官网 216 件装备复验)
-- +117~+125 是**装备需求属性**(需求力量/体质/敏捷/智慧/灵巧), 非加成属性
-- +205 = 最大负重
ALTER TABLE game_equipment ADD COLUMN IF NOT EXISTS max_load INT NOT NULL DEFAULT 0;
COMMENT ON COLUMN game_equipment.strength  IS '需求力量(+117)';
COMMENT ON COLUMN game_equipment.vitality  IS '需求体质/体力(+119)';
COMMENT ON COLUMN game_equipment.agility   IS '需求敏捷(+121)';
COMMENT ON COLUMN game_equipment.wisdom    IS '需求智慧(+123)';
COMMENT ON COLUMN game_equipment.dexterity IS '需求灵巧(+125)';

-- ===== folded from 0013_equip_names.sql =====

-- 字段正名(17173 资料站标注明确: "力量要求"/"敏捷要求", 表头有"装备等级"列)
-- 校验 217/218 = 99.5%
COMMENT ON COLUMN game_equipment.tier   IS '装备等级(+72), 17173表头"装备等级"列, 49票确认';
COMMENT ON COLUMN game_equipment.spirit IS '精神要求(+213), 16/16';

-- ===== folded from 0014_tasks.sql =====

-- 任务表(ov_task.bin, 366 行 × 868B)
-- 结构: id(+0) / 任务名(+12,128B) / 描述(+140,256B) / 发布NPC(+396,32B) / 地图(+428,32B) / 奖励(+460,120B)
-- 全部 366 行均解出名字, 与 map_npcs/map_defs 可按名关联
CREATE TABLE IF NOT EXISTS game_tasks (
    id     INT PRIMARY KEY,
    name   TEXT NOT NULL,
    descr  TEXT NOT NULL DEFAULT '',
    npc    TEXT NOT NULL DEFAULT '',
    map    TEXT NOT NULL DEFAULT '',
    reward TEXT NOT NULL DEFAULT ''
);
CREATE INDEX IF NOT EXISTS idx_tasks_npc ON game_tasks(npc);
CREATE INDEX IF NOT EXISTS idx_tasks_map ON game_tasks(map);

-- ===== folded from 0015_refine.sql =====

-- 精炼配方(ov_refine.bin, 3424 行 × 75B)
-- 结构: 等级(+0 u8) / 费用(+4 u32) / 成功率(+24 u16,%) / 材料1 id(+30)×数量(+32) / 材料2 id(+34)×数量(+36)
-- 验证: 材料ID全部命中真实物品(4001=铁矿石, 4160=蝴蝶翅膀); 费用递增+成功率递减+材料递增, 完全自洽
CREATE TABLE IF NOT EXISTS game_refine (
    row_no    INT PRIMARY KEY,
    level     INT NOT NULL,          -- 精炼等级
    cost      BIGINT NOT NULL,       -- 费用
    rate      INT NOT NULL,          -- 成功率(%)
    mat1_id   INT NOT NULL DEFAULT 0,
    mat1_qty  INT NOT NULL DEFAULT 0,
    mat2_id   INT NOT NULL DEFAULT 0,
    mat2_qty  INT NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_refine_level ON game_refine(level);

-- ===== folded from 0016_combine.sql =====

-- 合成配方(ov_combine.bin, 4782 行 × 75B) —— 与精炼表同族结构
-- 产物(+2) / 费用(+4 u32) / 成功率(+24 u16 %) / 材料1 id(+30)×数量(+32) / 材料2 id(+34)×数量(+36)
-- 验证: 产物与材料全部命中真实物品名, 语义自洽:
--   泳池派对*白(男)[43084] + 灵魂之证[10626] + 100000银 -> 真*泳池派对*白(男)[49105], 成功率100%
CREATE TABLE IF NOT EXISTS game_combine (
    row_no    INT PRIMARY KEY,
    product   INT NOT NULL,
    cost      BIGINT NOT NULL,
    rate      INT NOT NULL,
    mat1_id   INT NOT NULL DEFAULT 0,
    mat1_qty  INT NOT NULL DEFAULT 0,
    mat2_id   INT NOT NULL DEFAULT 0,
    mat2_qty  INT NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_combine_product ON game_combine(product);
CREATE INDEX IF NOT EXISTS idx_combine_mat1 ON game_combine(mat1_id);

-- ===== folded from 0017_pets.sql =====

-- 宠物表(ov_petgrow.bin, 504 行 × 260B)
-- 宠物 id **就是怪物 id**(1003=地翼魔, 与 game_monsters 一致)
-- 结构: id(+0) / 名字(+4,20B) / ?(+36) / 捕捉道具id(+38) / 捕捉率(+40, %) / 星级(+42)
-- 语义验证: 捕捉道具全部命中真实道具 —— 3382捕兽夹/3383玉净瓶/3384捆仙索/3388老君壶/3389天地绫
--   地翼魔→捆仙索 20% ; 海龟→捕兽夹 100% ; 雪女→玉净瓶 60%
CREATE TABLE IF NOT EXISTS game_pets (
    id          INT PRIMARY KEY,     -- = game_monsters.id
    name        TEXT NOT NULL,
    catch_item  INT NOT NULL DEFAULT 0,
    catch_rate  INT NOT NULL DEFAULT 0,
    star        INT NOT NULL DEFAULT 0,
    raw         BYTEA NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_pets_catchitem ON game_pets(catch_item);

-- ===== folded from 0018_misc_tables.sql =====

-- 镶嵌 / 生活技能 / 称号(结构均已解出并语义验证)
-- ov_enchase(91): 目标(+0)/费用(+4 u32)/核心道具(+14)/成功率(+24)/材料×2(+30,+34)
--   验证: 费用35万→85万递增, 太极碎片45→65递增, 核心道具"二级戒魂" —— 自洽
-- ov_lifeskill(54): 采集物id(+0) / 技能名(+16,16B, 如"伐木") / 动作词(+32,16B, 如"得到了")
-- ov_title(40行×14): 职业索引(+0) / 称号(+4 起每 32B), 共 560 个称号
CREATE TABLE IF NOT EXISTS game_enchase (
    row_no   INT PRIMARY KEY,
    target   INT NOT NULL,
    cost     BIGINT NOT NULL,
    core_item INT NOT NULL DEFAULT 0,
    rate     INT NOT NULL,
    mat1_id  INT NOT NULL DEFAULT 0, mat1_qty INT NOT NULL DEFAULT 0,
    mat2_id  INT NOT NULL DEFAULT 0, mat2_qty INT NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS game_lifeskill (
    node_id INT PRIMARY KEY,          -- 采集物 id
    skill   TEXT NOT NULL,            -- 伐木/采矿…
    action  TEXT NOT NULL DEFAULT ''
);
CREATE TABLE IF NOT EXISTS game_titles (
    job_idx INT NOT NULL,
    seq     INT NOT NULL,
    title   TEXT NOT NULL,
    PRIMARY KEY (job_idx, seq)
);

-- ===== folded from 0019_task_goal.sql =====

-- 任务目标结构解出(语义验证: 消灭甲虫→收集硬壳×10, 等级10~15)
ALTER TABLE game_tasks ADD COLUMN IF NOT EXISTS level_min INT NOT NULL DEFAULT 0;
ALTER TABLE game_tasks ADD COLUMN IF NOT EXISTS level_max INT NOT NULL DEFAULT 0;
ALTER TABLE game_tasks ADD COLUMN IF NOT EXISTS exp       BIGINT NOT NULL DEFAULT 0;
ALTER TABLE game_tasks ADD COLUMN IF NOT EXISTS goal_item INT NOT NULL DEFAULT 0;
ALTER TABLE game_tasks ADD COLUMN IF NOT EXISTS goal_qty  INT NOT NULL DEFAULT 0;

