-- ===== folded from 0021_monster_stats.sql =====

-- 怪物完整数值 —— 来源 research/fenfentu/monsters.json（2174 只）
--
-- 为什么需要这张迁移：客户端只有 ResCMon（14 字段纯外观），99 字段的 ResMonster 在服务端。
-- 粉粉兔的数据经我方客户端表六项对拍全中（经验曲线 150/150、怪名 2174/2174、
-- 装备 2042/2042、技能 232/232、掉落物按名 771/771、图↔怪 MVP 108 图 99 张完全一致）。
--
-- 攻防不是抄来的，是按 docs/怪物数值-定案.md 算出来的：
--     攻击中心 = 等级 × 2 × 类型倍率 × 身份倍率，物攻上下限为中心的 80% / 120%
--     普通身份倍率 1，精英 1.3，BOSS 2
--     10级以上：防御 = 等级，命中 = 等级 × 3
--     10级以下：防御 = max(1, 等级 × 0.4)，命中 = 等级 × 3
--     魔防仍为 max(1, 等级 × 0.4)，精英/BOSS 沿用原倍率

ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS hp          INT NOT NULL DEFAULT 0;
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS exp         INT NOT NULL DEFAULT 0;
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS move_speed  INT NOT NULL DEFAULT 0;
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS atk_speed   INT NOT NULL DEFAULT 1500;
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS elite_id    INT NOT NULL DEFAULT 0;  -- 光圈：指向精英版本的怪 id
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS kind        TEXT NOT NULL DEFAULT ''; -- 普通/精英/BOSS/采集物/场景物件
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS combat_type TEXT NOT NULL DEFAULT ''; -- 标准/重型/器物/法系/刺客
-- 以下为算出来的，不是原始数据
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS atk         INT NOT NULL DEFAULT 0; -- 攻击区间中心值
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS atk_min     INT NOT NULL DEFAULT 0;
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS atk_max     INT NOT NULL DEFAULT 0;
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS matk        INT NOT NULL DEFAULT 0;
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS def         INT NOT NULL DEFAULT 0;
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS mdef        INT NOT NULL DEFAULT 0;
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS hit         INT NOT NULL DEFAULT 0;
-- 原服务端用 CriticalAdd × ResMonDyn.ReviseCritical；两张权威数值表均不在客户端。
-- 权威逐怪数值缺失，先采用统一 5% 基线，保留逐怪覆盖入口，物理/魔法分开配置。
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS crit_rate    INT NOT NULL DEFAULT 500 CHECK (crit_rate BETWEEN 0 AND 10000);
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS mcrit_rate   INT NOT NULL DEFAULT 500 CHECK (mcrit_rate BETWEEN 0 AND 10000);
-- AI（docs/怪物数值-定案.md 第三节）
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS aggressive  BOOL NOT NULL DEFAULT FALSE; -- AttackPatrol
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS can_attack  BOOL NOT NULL DEFAULT TRUE;  -- false: 可被击杀但不会主动或反击
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS basic_attack_enabled BOOL NOT NULL DEFAULT TRUE;
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS call_help   BOOL NOT NULL DEFAULT FALSE; -- HelpPatrol
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS view_dist   INT NOT NULL DEFAULT 400;
ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS trace_dist  INT NOT NULL DEFAULT 600;

CREATE INDEX IF NOT EXISTS idx_monsters_kind ON game_monsters(kind);
CREATE INDEX IF NOT EXISTS idx_monsters_hp   ON game_monsters(hp);

-- 怪物技能。monsters.json 只给 id + 等级；释放概率/血线触发在服务端专有结构里，没有。
CREATE TABLE IF NOT EXISTS game_monster_ai_templates (
    id                  TEXT PRIMARY KEY,
    view_dist           INT NOT NULL CHECK (view_dist >= 0),
    trace_dist          INT NOT NULL CHECK (trace_dist >= view_dist),
    basic_attack_dist   INT NOT NULL CHECK (basic_attack_dist > 0),
    keep_dist           INT NOT NULL DEFAULT 0 CHECK (keep_dist >= 0),
    help_radius         INT NOT NULL DEFAULT 0 CHECK (help_radius >= 0),
    skill_check_ms      INT NOT NULL DEFAULT 1000 CHECK (skill_check_ms >= 100),
    global_cooldown_ms  INT NOT NULL DEFAULT 500 CHECK (global_cooldown_ms >= 100)
);
     skill_check_ms,global_cooldown_ms)
VALUES
    ('passive',0,0,75,0,0,1000,1000),
    ('melee',400,600,75,0,250,1000,500),
    ('caster',400,600,75,0,250,800,500),
    ('turret',400,600,75,0,250,800,500),
    ('elite',400,600,85,0,300,700,400),
    ('elite_caster',400,600,85,0,350,600,350),
    ('boss_melee',400,600,100,0,400,500,400),
    ('boss_caster',400,600,100,0,500,400,300)
ON CONFLICT (id) DO UPDATE SET
    view_dist=EXCLUDED.view_dist, trace_dist=EXCLUDED.trace_dist,
    basic_attack_dist=EXCLUDED.basic_attack_dist, keep_dist=EXCLUDED.keep_dist,
    help_radius=EXCLUDED.help_radius, skill_check_ms=EXCLUDED.skill_check_ms,
    global_cooldown_ms=EXCLUDED.global_cooldown_ms;

ALTER TABLE game_monsters ADD COLUMN IF NOT EXISTS ai_template TEXT NOT NULL DEFAULT 'melee';
DO $$ BEGIN
    ALTER TABLE game_monsters ADD CONSTRAINT fk_game_monsters_ai_template
        FOREIGN KEY (ai_template) REFERENCES game_monster_ai_templates(id);
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

CREATE TABLE IF NOT EXISTS game_monster_skills (
    monster_id INT  NOT NULL,
    slot       INT  NOT NULL,           -- 同一怪的第几个技能
    kind       TEXT NOT NULL,           -- enemy 对敌 / self 对己 / immune 免疫
    skill_id   INT  NOT NULL,           -- 对应 ov_skilldesc.skill_id
    skill_lv   INT  NOT NULL DEFAULT 1,
    name       TEXT NOT NULL DEFAULT '',
    priority            INT  NOT NULL DEFAULT 100,
    chance_bp           INT  NOT NULL DEFAULT 3000 CHECK (chance_bp BETWEEN 0 AND 10000),
    cooldown_ms         INT  NOT NULL DEFAULT 5000 CHECK (cooldown_ms >= 0),
    initial_delay_ms    INT  NOT NULL DEFAULT 1500 CHECK (initial_delay_ms >= 0),
    min_hp_pct          INT  NOT NULL DEFAULT 0 CHECK (min_hp_pct BETWEEN 0 AND 100),
    max_hp_pct          INT  NOT NULL DEFAULT 100 CHECK (max_hp_pct BETWEEN 0 AND 100),
    max_casts_per_life  INT  NOT NULL DEFAULT 0 CHECK (max_casts_per_life >= 0),
    fallback_damage_pct INT  NOT NULL DEFAULT 0 CHECK (fallback_damage_pct >= 0),
    enabled             BOOL NOT NULL DEFAULT TRUE,
    disabled_reason     TEXT NOT NULL DEFAULT '',
    PRIMARY KEY (monster_id, kind, slot)
);
ALTER TABLE game_monster_skills
    ADD COLUMN IF NOT EXISTS max_casts_per_life INT NOT NULL DEFAULT 0
    CHECK (max_casts_per_life >= 0);
ALTER TABLE game_monster_skills
    ADD COLUMN IF NOT EXISTS disabled_reason TEXT NOT NULL DEFAULT '';
CREATE INDEX IF NOT EXISTS idx_monskill_skill ON game_monster_skills(skill_id);

-- 怪物技能的服务端结果。skill_lv=0 表示适用于该技能全部等级；具体等级行在
-- 载入时叠加其后。直接伤害/治疗/状态与召唤、驱散等场景动作统一从这里闭合。
CREATE TABLE IF NOT EXISTS game_monster_skill_effects (
    skill_id            INT  NOT NULL,
    skill_lv            INT  NOT NULL DEFAULT 0,
    seq                 INT  NOT NULL,
    effect_kind         TEXT NOT NULL CHECK (effect_kind IN
        ('damage','damage_mp','heal','status','random_status','dispel_beneficial','dispel_harmful',
         'clear_aggro','despawn','summon')),
    power_pct           INT  NOT NULL DEFAULT 0,
    heal_max_hp_pct     INT  NOT NULL DEFAULT 0,
    flat_value          INT  NOT NULL DEFAULT 0,
    status_id           INT  NOT NULL DEFAULT 0,
    status_level_mode   TEXT NOT NULL DEFAULT 'same' CHECK
        (status_level_mode IN ('same','offset','fixed')),
    status_level_value  INT  NOT NULL DEFAULT 0,
    duration_sec        INT  NOT NULL DEFAULT 0,
    summon_monster_id   INT  NOT NULL DEFAULT 0,
    summon_count        INT  NOT NULL DEFAULT 0,
    chance_bp           INT  NOT NULL DEFAULT 10000 CHECK (chance_bp BETWEEN 1 AND 10000),
    guaranteed_hit      BOOL NOT NULL DEFAULT FALSE,
    override_hurt_type  BOOL NOT NULL DEFAULT FALSE,
    hurt_type_override  INT  NOT NULL DEFAULT 0 CHECK (hurt_type_override BETWEEN 0 AND 13),
    PRIMARY KEY (skill_id, skill_lv, seq)
);
ALTER TABLE game_monster_skill_effects
    ADD COLUMN IF NOT EXISTS chance_bp INT NOT NULL DEFAULT 10000
    CHECK (chance_bp BETWEEN 1 AND 10000);
ALTER TABLE game_monster_skill_effects
    ADD COLUMN IF NOT EXISTS guaranteed_hit BOOL NOT NULL DEFAULT FALSE;
ALTER TABLE game_monster_skill_effects
    ADD COLUMN IF NOT EXISTS override_hurt_type BOOL NOT NULL DEFAULT FALSE;
ALTER TABLE game_monster_skill_effects
    ADD COLUMN IF NOT EXISTS hurt_type_override INT NOT NULL DEFAULT 0
    CHECK (hurt_type_override BETWEEN 0 AND 13);
CREATE INDEX IF NOT EXISTS idx_monster_skill_effects_skill
    ON game_monster_skill_effects(skill_id, skill_lv);

-- 五职业主动技能的显式服务端结果。effect_order 定义同一技能内的结算顺序；
-- 未迁入本表的旧技能暂时继续从 ov_skilldesc.desc_ 解析单一直接效果。
CREATE TABLE IF NOT EXISTS game_skill_effects (
    skill_id          INT  NOT NULL,
    skill_level       INT  NOT NULL CHECK (skill_level > 0),
    effect_order      INT  NOT NULL CHECK (effect_order > 0),
    effect_kind       TEXT NOT NULL CHECK (length(effect_kind) > 0),
    power_pct         INT  NOT NULL DEFAULT 0 CHECK (power_pct >= 0),
    max_resource_pct  INT  NOT NULL DEFAULT 0 CHECK (max_resource_pct >= 0),
    flat_value        INT  NOT NULL DEFAULT 0 CHECK (flat_value >= 0),
    guaranteed_hit    BOOL NOT NULL DEFAULT FALSE,
    chance_bp         INT  NOT NULL DEFAULT 10000 CHECK (chance_bp BETWEEN 1 AND 10000),
    effect_target     TEXT NOT NULL DEFAULT 'target' CHECK (effect_target IN ('target','caster')),
    requires_previous_landed BOOL NOT NULL DEFAULT FALSE,
    weapon_durability_pct INT NOT NULL DEFAULT 0
        CHECK (weapon_durability_pct BETWEEN 0 AND 100),
    loss_refund_pct INT NOT NULL DEFAULT 0
        CHECK (loss_refund_pct BETWEEN 0 AND 100),
    PRIMARY KEY (skill_id, skill_level, effect_order)
);
CREATE INDEX IF NOT EXISTS idx_skill_effects_kind ON game_skill_effects(effect_kind);

-- 职业范围技能的中心语义。形状和尺寸来自 gamedata.ov_skilldesc 的
-- range_type/radius/angle/width/height；原始表没有“以自身还是目标为中心”字段，
-- 因而只把技能说明中已经明确给出的这一维补成结构化规则。
CREATE TABLE IF NOT EXISTS game_skill_area_rules (
    skill_id INT  PRIMARY KEY CHECK (skill_id > 0),
    center   TEXT NOT NULL CHECK (center IN ('caster','target'))
);

ON CONFLICT (skill_id) DO UPDATE SET center = EXCLUDED.center;

-- 选择性驱散的状态白名单。概率放在主效果行，保证同一次施法只做一次成功判定，
-- 成功后原子移除该效果列出的全部匹配状态。
CREATE TABLE IF NOT EXISTS game_skill_effect_remove_statuses (
    skill_id       INT NOT NULL,
    skill_level    INT NOT NULL,
    effect_order   INT NOT NULL,
    status_id      INT NOT NULL CHECK (status_id > 0),
    PRIMARY KEY (skill_id, skill_level, effect_order, status_id),
    FOREIGN KEY (skill_id, skill_level, effect_order)
        REFERENCES game_skill_effects(skill_id, skill_level, effect_order)
        ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_skill_effect_remove_status
    ON game_skill_effect_remove_statuses(status_id);

-- 五职业被动技能的结算修正。被动技能本身仍来自 ov_skilldesc；这里只保存
-- 客户端描述中已经给出完整数值、需要在主动技能或受击时查询的关系。
CREATE TABLE IF NOT EXISTS game_skill_passive_modifiers (
    passive_skill_id    INT NOT NULL CHECK (passive_skill_id > 0),
    passive_skill_level INT NOT NULL CHECK (passive_skill_level > 0),
    modifier_order      INT NOT NULL CHECK (modifier_order > 0),
    modifier_kind       TEXT NOT NULL CHECK (modifier_kind IN (
        'skill_damage_pct', 'effect_source_attack_pct',
        'cast_time_reduction_pct', 'cast_interrupt_reduction_pct', 'incoming_magic_half_chance',
        'stealth_duration_sec', 'stealth_move_speed_pct',
        'stealth_damage_pct', 'preserve_invisible_chance',
        'skill_durability_reduction_pct',
        'attack_durability_reduction_pct',
        'trap_half_damage_chance',
        'status_physical_damage_taken_pct'
    )),
    target_skill_id     INT NOT NULL DEFAULT 0 CHECK (target_skill_id >= 0),
    effect_kind         TEXT NOT NULL DEFAULT '' CHECK (effect_kind IN (
        '', 'damage_mp', 'restore_hp', 'restore_mp'
    )),
    value               INT NOT NULL CHECK (value BETWEEN 1 AND 100),
    PRIMARY KEY (passive_skill_id, passive_skill_level, modifier_order),
    CHECK (
        (modifier_kind = 'skill_damage_pct' AND target_skill_id > 0 AND effect_kind = '') OR
        (modifier_kind = 'effect_source_attack_pct' AND target_skill_id > 0 AND effect_kind <> '') OR
        (modifier_kind IN (
            'cast_time_reduction_pct', 'cast_interrupt_reduction_pct', 'incoming_magic_half_chance',
            'attack_durability_reduction_pct', 'trap_half_damage_chance'
        )
            AND target_skill_id = 0 AND effect_kind = '') OR
        (modifier_kind IN (
            'stealth_duration_sec', 'stealth_move_speed_pct',
            'stealth_damage_pct', 'preserve_invisible_chance',
            'skill_durability_reduction_pct',
            'status_physical_damage_taken_pct'
        ) AND target_skill_id > 0 AND effect_kind = '')
    )
);
CREATE INDEX IF NOT EXISTS idx_skill_passive_modifier_target
    ON game_skill_passive_modifiers(target_skill_id)
    WHERE target_skill_id > 0;

-- 被动技能对角色基础属性的修正。required_equip_type 使用 ov_arm.type；
-- 0 表示无装备限制，非零时只有实际装备对应类型才生效。
CREATE TABLE IF NOT EXISTS game_skill_passive_stat_modifiers (
    passive_skill_id    INT NOT NULL CHECK (passive_skill_id > 0),
    passive_skill_level INT NOT NULL CHECK (passive_skill_level > 0),
    modifier_order      INT NOT NULL CHECK (modifier_order > 0),
    attr_id             INT NOT NULL CHECK (attr_id > 0),
    value               INT NOT NULL,
    mode                INT NOT NULL CHECK (mode IN (0,1)),
    required_equip_type INT NOT NULL DEFAULT 0 CHECK (required_equip_type >= 0),
    PRIMARY KEY (passive_skill_id, passive_skill_level, modifier_order)
);

-- 只针对某一种异常状态的被动抵抗率；与装备提供的通用不良状态抗性相加，
-- 最终仍受统一 90% 上限约束。
CREATE TABLE IF NOT EXISTS game_skill_passive_status_resists (
    passive_skill_id    INT NOT NULL CHECK (passive_skill_id > 0),
    passive_skill_level INT NOT NULL CHECK (passive_skill_level > 0),
    resist_order        INT NOT NULL CHECK (resist_order > 0),
    status_id           INT NOT NULL CHECK (status_id > 0),
    resist_pct          INT NOT NULL CHECK (resist_pct BETWEEN 1 AND 100),
    PRIMARY KEY (passive_skill_id, passive_skill_level, resist_order)
);
CREATE INDEX IF NOT EXISTS idx_skill_passive_status_resist_status
    ON game_skill_passive_status_resists(status_id);

-- 被动技能为指定主动技能追加的概率状态。status_level/duration_sec 已由
-- 技能说明或官方状态等级闭合；duration_sec=0 表示使用状态定义自身时长。
CREATE TABLE IF NOT EXISTS game_skill_passive_trigger_statuses (
    passive_skill_id    INT NOT NULL CHECK (passive_skill_id > 0),
    passive_skill_level INT NOT NULL CHECK (passive_skill_level > 0),
    trigger_order       INT NOT NULL CHECK (trigger_order > 0),
    target_skill_id     INT NOT NULL CHECK (target_skill_id > 0),
    status_id           INT NOT NULL CHECK (status_id > 0),
    status_level        INT NOT NULL CHECK (status_level > 0),
    chance_bp           INT NOT NULL CHECK (chance_bp BETWEEN 1 AND 10000),
    duration_sec        INT NOT NULL DEFAULT 0 CHECK (duration_sec >= 0),
    PRIMARY KEY (passive_skill_id, passive_skill_level, trigger_order)
);
CREATE INDEX IF NOT EXISTS idx_skill_passive_trigger_target
    ON game_skill_passive_trigger_statuses(target_skill_id);

-- 被动为目标主动技能原有状态追加的属性词条。与 trigger_statuses 不同，
-- 它不会创建第二个状态，而是继承原状态的持续时间与覆盖关系。
CREATE TABLE IF NOT EXISTS game_skill_passive_status_affixes (
    passive_skill_id    INT NOT NULL CHECK (passive_skill_id > 0),
    passive_skill_level INT NOT NULL CHECK (passive_skill_level > 0),
    modifier_order      INT NOT NULL CHECK (modifier_order > 0),
    target_skill_id     INT NOT NULL CHECK (target_skill_id > 0),
    status_id           INT NOT NULL CHECK (status_id > 0),
    attr_id             INT NOT NULL CHECK (attr_id > 0),
    value               INT NOT NULL,
    mode                INT NOT NULL CHECK (mode IN (0,1)),
    PRIMARY KEY (passive_skill_id, passive_skill_level, modifier_order)
);
CREATE INDEX IF NOT EXISTS idx_skill_passive_status_affix_target
    ON game_skill_passive_status_affixes(target_skill_id,status_id);

-- 被动为指定主动技能追加的有序直接效果。当前只开放已闭合的概率击退；
-- flat_value 使用世界像素距离，chance_bp 使用万分比。
CREATE TABLE IF NOT EXISTS game_skill_passive_trigger_effects (
    passive_skill_id    INT NOT NULL CHECK (passive_skill_id > 0),
    passive_skill_level INT NOT NULL CHECK (passive_skill_level > 0),
    trigger_order       INT NOT NULL CHECK (trigger_order > 0),
    target_skill_id     INT NOT NULL CHECK (target_skill_id > 0),
    effect_kind         TEXT NOT NULL CHECK (effect_kind IN ('knockback')),
    flat_value          INT NOT NULL CHECK (flat_value > 0),
    chance_bp           INT NOT NULL CHECK (chance_bp BETWEEN 1 AND 10000),
    PRIMARY KEY (passive_skill_id, passive_skill_level, trigger_order)
);
CREATE INDEX IF NOT EXISTS idx_skill_passive_trigger_effect_target
    ON game_skill_passive_trigger_effects(target_skill_id);

-- 成功闪避后的被动反击。反击属于独立响应，不占用玩家主动攻击冷却；
-- required_equip_type 保证反击术只在双刃装备条件下生效。
CREATE TABLE IF NOT EXISTS game_skill_passive_counterattacks (
    passive_skill_id    INT NOT NULL CHECK (passive_skill_id > 0),
    passive_skill_level INT NOT NULL CHECK (passive_skill_level > 0),
    chance_bp           INT NOT NULL CHECK (chance_bp BETWEEN 1 AND 10000),
    damage_pct          INT NOT NULL CHECK (damage_pct > 0),
    required_equip_type INT NOT NULL DEFAULT 0 CHECK (required_equip_type >= 0),
    PRIMARY KEY (passive_skill_id, passive_skill_level)
);

-- 技能描述参数完整、但官方状态表没有等价等级时使用的服务端状态定义。
-- status_id 采用来源技能号，避免和 1001.. 状态表身份冲突，也让客户端展示来源稳定。
CREATE TABLE IF NOT EXISTS game_custom_statuses (
    status_id        INT NOT NULL CHECK (status_id > 0),
    status_level     INT NOT NULL CHECK (status_level > 0),
    name             TEXT NOT NULL CHECK (length(name) > 0),
    description      TEXT NOT NULL DEFAULT '',
    status_type      SMALLINT NOT NULL CHECK (status_type BETWEEN 0 AND 6),
    duration_sec     INT NOT NULL CHECK (duration_sec > 0),
    interval_sec     INT NOT NULL DEFAULT 0 CHECK (interval_sec >= 0),
    hp_change_value  INT NOT NULL DEFAULT 0,
    hp_change_mode   INT NOT NULL DEFAULT 0 CHECK (hp_change_mode IN (0, 1)),
    physical_damage_reduction_pct INT NOT NULL DEFAULT 0
        CHECK (physical_damage_reduction_pct BETWEEN 0 AND 100),
    magic_damage_reduction_pct INT NOT NULL DEFAULT 0
        CHECK (magic_damage_reduction_pct BETWEEN 0 AND 100),
	physical_damage_taken_pct INT NOT NULL DEFAULT 0
		CHECK (physical_damage_taken_pct BETWEEN 0 AND 100),
	magic_damage_taken_pct INT NOT NULL DEFAULT 0
		CHECK (magic_damage_taken_pct BETWEEN 0 AND 100),
    damage_shield    INT NOT NULL DEFAULT 0 CHECK (damage_shield >= 0),
    attack_cap       INT CHECK (attack_cap >= 0),
    prevent_invisible BOOL NOT NULL DEFAULT FALSE,
    CHECK (hp_change_value = 0 OR interval_sec > 0),
    PRIMARY KEY (status_id, status_level)
);

CREATE TABLE IF NOT EXISTS game_custom_status_affixes (
    status_id       INT NOT NULL,
    status_level    INT NOT NULL,
    affix_order     INT NOT NULL CHECK (affix_order > 0),
    attr_id         INT NOT NULL CHECK (attr_id > 0),
    value           INT NOT NULL,
    mode            INT NOT NULL CHECK (mode IN (0, 1)),
    PRIMARY KEY (status_id, status_level, affix_order),
    FOREIGN KEY (status_id, status_level)
        REFERENCES game_custom_statuses(status_id, status_level) ON DELETE CASCADE
);

-- 五职业主动技能对官方状态定义的显式映射。技能配置只决定施加哪一级状态及
-- 可选的技能时长/说明覆盖；状态本身的属性、周期和控制语义仍来自 gamedata 状态表。
CREATE TABLE IF NOT EXISTS game_skill_statuses (
    skill_id       INT NOT NULL,
    skill_level    INT NOT NULL CHECK (skill_level > 0),
    status_order   INT NOT NULL CHECK (status_order > 0),
    status_id      INT NOT NULL CHECK (status_id > 0),
    status_level   INT NOT NULL CHECK (status_level > 0),
	chance_bp     INT NOT NULL DEFAULT 10000 CHECK (chance_bp BETWEEN 1 AND 10000),
    duration_sec   INT NOT NULL DEFAULT 0 CHECK (duration_sec >= 0),
    description_override TEXT NOT NULL DEFAULT '',
    instant_death_immune BOOL NOT NULL DEFAULT FALSE,
    PRIMARY KEY (skill_id, skill_level, status_order)
);
CREATE INDEX IF NOT EXISTS idx_skill_statuses_status
    ON game_skill_statuses(status_id, status_level);

-- 怪物掉落。两种形态：具名物品（id+name）与随机装备（种类+等级范围）。
CREATE TABLE IF NOT EXISTS game_monster_drops (
    monster_id INT  NOT NULL,
    seq        INT  NOT NULL,
    rate       REAL NOT NULL,           -- 概率（百分比，如 31.365556）
    -- 具名物品
    item_id    INT  NOT NULL DEFAULT 0, -- 已按名字重映射到我方 ov_item/ov_arm 的 index
    item_name  TEXT NOT NULL DEFAULT '',
    item_src   TEXT NOT NULL DEFAULT '',-- item / arm / unmapped
    -- 随机装备
    kind_name  TEXT NOT NULL DEFAULT '',-- 长剑 / 法杖 / 头盔 …
    lv_min     INT  NOT NULL DEFAULT 0,
    lv_max     INT  NOT NULL DEFAULT 0,
    PRIMARY KEY (monster_id, seq)
);
CREATE INDEX IF NOT EXISTS idx_mondrop_item ON game_monster_drops(item_id);

-- 装备附加属性。链路：ov_arm.row_no → ov_arm_entry.card_id → ov_card → ov_card_entry
-- 这是客户端里真实存在的数据，此前一直没有物化（曾误判为"客户端没有"）。
CREATE TABLE IF NOT EXISTS game_equip_extra (
    arm_id   INT  NOT NULL,
    seq      INT  NOT NULL,
    attr_id  INT  NOT NULL,             -- 见 docs/表索引.md 的 attr_id 字典
    attr_name TEXT NOT NULL DEFAULT '',
    value    INT  NOT NULL,
    mode     INT  NOT NULL DEFAULT 0,   -- 0=绝对值 1=百分比
    prob     INT  NOT NULL DEFAULT 100,
    PRIMARY KEY (arm_id, seq)
);
CREATE INDEX IF NOT EXISTS idx_equipextra_attr ON game_equip_extra(attr_id);

-- ===== folded from 0022_work_stamina.sql =====

-- 打工与耐力：点卡时代 → 免费游戏的节奏改造
--
-- 原版是按"占着号挂机"设计的：耐力半小时回 2 点、上限 100，打工每 10 分钟扣 2 点，
-- 100 点能挂 500 分钟（8.3 小时），每 180 秒结算一次 = 一轮 166 次。
--
-- 免费游戏不需要玩家挂 8 小时。改成：
--     耐力      每天回满一次，一次 100 点
--     打工消耗  每分钟 -1 点  →  100 分钟耗尽
--     结算间隔  全部 ÷5
--
-- **总收益与单次收益都不变**：100 分钟 ÷ 36 秒 = 166 次，与原版 500 分钟 ÷ 180 秒 相同。
-- 只是把 8 小时压缩进 100 分钟。

CREATE TABLE IF NOT EXISTS game_work (
    work_id     INT  PRIMARY KEY,       -- 对应 ov_work.row_no
    title       TEXT NOT NULL,          -- 打扫卫生中的 / 钓鱼中的 …
    lv_min      INT  NOT NULL,
    lv_max      INT  NOT NULL,
    unit_sec    INT  NOT NULL,          -- 结算间隔（已 ÷5）
    unit_sec_v  INT  NOT NULL,          -- 原版值，留着对照
    exp         INT  NOT NULL DEFAULT 0,
    honor       INT  NOT NULL DEFAULT 0,
    coin        INT  NOT NULL DEFAULT 0,
    coin_prob   INT  NOT NULL DEFAULT 1000   -- 千分比
);

-- 耐力规则（单行配置，服务端读它）
CREATE TABLE IF NOT EXISTS game_stamina_rule (
    id             INT  PRIMARY KEY DEFAULT 1,
    max_points     INT  NOT NULL DEFAULT 100,   -- 上限
    refill_daily   BOOL NOT NULL DEFAULT TRUE,  -- 每天回满（不再按半小时滴回）
    cost_per_min   INT  NOT NULL DEFAULT 1,     -- 打工每分钟消耗
    CHECK (id = 1)
);
VALUES (1, 100, TRUE, 1)
ON CONFLICT (id) DO UPDATE
  SET max_points = 100, refill_daily = TRUE, cost_per_min = 1;

-- 坐下休息规则（单行配置，服务端读它）
CREATE TABLE IF NOT EXISTS game_rest_rule (
    id                  INT PRIMARY KEY DEFAULT 1,
    interval_ms         INT NOT NULL,
    heal_max_hp_pct     INT NOT NULL,
    heal_flat           INT NOT NULL,
    CHECK (id = 1),
    CHECK (interval_ms > 0),
    CHECK (heal_max_hp_pct BETWEEN 0 AND 100),
    CHECK (heal_flat >= 0),
    CHECK (heal_max_hp_pct > 0 OR heal_flat > 0)
);
VALUES (1, 2000, 5, 100)
ON CONFLICT (id) DO UPDATE
  SET interval_ms = 2000, heal_max_hp_pct = 5, heal_flat = 100;

-- 战斗命中时序。远程普攻速度使用现有职业弹道技能换算速度的近似均值；
-- 技能自身速度继续由 ov_skilldesc.dist / ov_skillshow.fly_show_delay 逐技能推导。
CREATE TABLE IF NOT EXISTS game_combat_timing_rule (
    id                                SMALLINT PRIMARY KEY CHECK (id = 1),
    melee_hit_delay_ms                INT NOT NULL CHECK (melee_hit_delay_ms >= 0),
    ranged_basic_speed_px_per_sec     INT NOT NULL CHECK (ranged_basic_speed_px_per_sec > 0),
    cast_interrupt_base_bp           INT NOT NULL DEFAULT 4000 CHECK (cast_interrupt_base_bp BETWEEN 1 AND 10000),
    cast_interrupt_min_bp            INT NOT NULL DEFAULT 500 CHECK (cast_interrupt_min_bp BETWEEN 1 AND cast_interrupt_base_bp)
);
VALUES (1, 350, 800, 4000, 500)
ON CONFLICT (id) DO UPDATE SET
    melee_hit_delay_ms = EXCLUDED.melee_hit_delay_ms,
    ranged_basic_speed_px_per_sec = EXCLUDED.ranged_basic_speed_px_per_sec,
    cast_interrupt_base_bp = EXCLUDED.cast_interrupt_base_bp,
    cast_interrupt_min_bp = EXCLUDED.cast_interrupt_min_bp;

-- 玩家邮件：正文与附件托管都按角色持久化。发送/领取时与角色完整快照同事务提交，
-- 避免附件同时存在于背包和邮箱，或领取后重登再次出现。
CREATE TABLE IF NOT EXISTS game_mail_rule (
    id          SMALLINT PRIMARY KEY CHECK (id = 1),
    capacity    INT NOT NULL CHECK (capacity > 0),
    expire_days INT NOT NULL CHECK (expire_days > 0),
    max_attach  INT NOT NULL CHECK (max_attach BETWEEN 1 AND 255)
);
VALUES (1, 100, 30, 5)
ON CONFLICT (id) DO UPDATE SET
    capacity = EXCLUDED.capacity,
    expire_days = EXCLUDED.expire_days,
    max_attach = EXCLUDED.max_attach;

-- QA 客户端 ChatUI.Channels 的现有四频道。接收范围与限流放数据库，避免把
-- 世界/队伍频道规则散落在会话分支中；家族频道待家族成员事实源建立后启用。
CREATE TABLE IF NOT EXISTS game_chat_channel_rules (
    channel      SMALLINT PRIMARY KEY CHECK (channel BETWEEN 0 AND 255),
    scope        TEXT NOT NULL CHECK (scope IN ('map','party','family','world')),
    cooldown_ms  INT NOT NULL CHECK (cooldown_ms >= 0),
    max_shares   INT NOT NULL CHECK (max_shares BETWEEN 0 AND 4)
);
ON CONFLICT (channel) DO UPDATE SET
    scope = EXCLUDED.scope,
    cooldown_ms = EXCLUDED.cooldown_ms,
    max_shares = EXCLUDED.max_shares;

-- 魔法衣橱。新角色未开启（无 character_wardrobes 行）；消耗 10 把钥匙一次
-- 开启 10 格。ov_magicwardrobe 给出第 11..200 格各自所需的钥匙数量。
CREATE TABLE IF NOT EXISTS game_wardrobe_rule (
    id                SMALLINT PRIMARY KEY CHECK (id = 1),
    key_item_id       INT NOT NULL CHECK (key_item_id > 0),
    open_key_cost     INT NOT NULL CHECK (open_key_cost > 0),
    open_capacity     INT NOT NULL CHECK (open_capacity > 0),
    max_capacity      INT NOT NULL CHECK (max_capacity >= open_capacity AND max_capacity <= 32767)
);
VALUES (1,26955,10,10,200)
ON CONFLICT (id) DO UPDATE SET
    key_item_id = EXCLUDED.key_item_id,
    open_key_cost = EXCLUDED.open_key_cost,
    open_capacity = EXCLUDED.open_capacity,
    max_capacity = EXCLUDED.max_capacity;

CREATE TABLE IF NOT EXISTS character_wardrobes (
    char_id   BIGINT PRIMARY KEY REFERENCES characters(id) ON DELETE CASCADE,
    capacity  INT NOT NULL CHECK (capacity > 0 AND capacity <= 32767)
);

CREATE TABLE IF NOT EXISTS character_wardrobe_items (
    char_id   BIGINT NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
    item_id   INT NOT NULL CHECK (item_id > 0),
    category  SMALLINT NOT NULL CHECK (category BETWEEN 0 AND 4),
    worn      BOOLEAN NOT NULL DEFAULT FALSE,
    position  INT NOT NULL CHECK (position >= 0),
    PRIMARY KEY (char_id,item_id),
    UNIQUE (char_id,position)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_character_wardrobe_worn_category
    ON character_wardrobe_items(char_id,category) WHERE worn;

-- 玩家摆摊托管。出售摊的物品从背包移入这里；收购摊仅保存欲购数量与单价，
-- 成交时再检查并扣除摊主余额。正常退出先归还出售物，进程崩溃则下次登录
-- 从这些行恢复，不能让托管物权只存在于内存。
CREATE TABLE IF NOT EXISTS character_stalls (
    char_id     BIGINT PRIMARY KEY REFERENCES characters(id) ON DELETE CASCADE,
    stall_type  SMALLINT NOT NULL CHECK (stall_type BETWEEN 0 AND 1),
    name        TEXT NOT NULL DEFAULT '',
    CONSTRAINT character_stalls_name_nonempty CHECK (length(name) > 0)
);
CREATE TABLE IF NOT EXISTS character_stall_items (
    char_id               BIGINT NOT NULL REFERENCES character_stalls(char_id) ON DELETE CASCADE,
    position              INT NOT NULL CHECK (position >= 0),
    uid                   BIGINT NOT NULL DEFAULT 0,
    item_id               INT NOT NULL CHECK (item_id > 0),
    count                 INT NOT NULL CHECK (count > 0),
    unit_price            BIGINT NOT NULL CHECK (unit_price > 0),
    durability            INT NOT NULL DEFAULT 0,
    max_durability        INT NOT NULL DEFAULT 0 CHECK (max_durability >= 0),
    durability_wear_raw   INT NOT NULL DEFAULT 0 CHECK (durability_wear_raw BETWEEN 0 AND 299),
    bound                 BOOLEAN NOT NULL DEFAULT FALSE,
    locked                BOOLEAN NOT NULL DEFAULT FALSE,
    refine_level          INT NOT NULL DEFAULT 0 CHECK (refine_level >= 0),
    socket_count          SMALLINT NOT NULL DEFAULT 0 CHECK (socket_count BETWEEN 0 AND 5),
    sockets               INT[] NOT NULL DEFAULT ARRAY[0,0,0,0,0] CHECK (cardinality(sockets) = 5),
    wash_quality          SMALLINT NOT NULL DEFAULT 0 CHECK (wash_quality BETWEEN 0 AND 4),
    wash_count            SMALLINT NOT NULL DEFAULT 0 CHECK (wash_count BETWEEN 0 AND 4),
    wash_attrs            INT[] NOT NULL DEFAULT ARRAY[0,0,0,0] CHECK (cardinality(wash_attrs) = 4),
    wash_values           INT[] NOT NULL DEFAULT ARRAY[0,0,0,0] CHECK (cardinality(wash_values) = 4),
    wash_modes            INT[] NOT NULL DEFAULT ARRAY[0,0,0,0] CHECK (cardinality(wash_modes) = 4),
    PRIMARY KEY (char_id,position),
    UNIQUE (char_id,item_id)
);
CREATE TABLE IF NOT EXISTS character_stall_sales (
    char_id      BIGINT NOT NULL REFERENCES character_stalls(char_id) ON DELETE CASCADE,
    position     INT NOT NULL CHECK (position >= 0),
    occurred_at  TIMESTAMPTZ NOT NULL,
    item_name    TEXT NOT NULL DEFAULT '',
    count        INT NOT NULL CHECK (count > 0),
    money        BIGINT NOT NULL CHECK (money > 0),
    PRIMARY KEY (char_id,position)
);

CREATE TABLE IF NOT EXISTS character_mails (
    id            BIGSERIAL PRIMARY KEY,
    recipient_id  BIGINT NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
    sender_id     BIGINT NOT NULL DEFAULT 0 CHECK (sender_id >= 0),
    sender_name   TEXT NOT NULL DEFAULT '',
    title         TEXT NOT NULL DEFAULT '',
    body          TEXT NOT NULL DEFAULT '',
    money         BIGINT NOT NULL DEFAULT 0 CHECK (money >= 0),
    caiyu         BIGINT NOT NULL DEFAULT 0 CHECK (caiyu >= 0),
    mail_type     SMALLINT NOT NULL DEFAULT 0 CHECK (mail_type BETWEEN 0 AND 255),
    is_read       BOOLEAN NOT NULL DEFAULT FALSE,
    returned      BOOLEAN NOT NULL DEFAULT FALSE,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at    TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_character_mails_recipient
    ON character_mails(recipient_id, created_at DESC, id DESC);

CREATE TABLE IF NOT EXISTS character_mail_attachments (
    mail_id              BIGINT NOT NULL REFERENCES character_mails(id) ON DELETE CASCADE,
    ordinal              INT NOT NULL CHECK (ordinal >= 0),
    uid                  BIGINT NOT NULL DEFAULT 0,
    item_id              INT NOT NULL CHECK (item_id > 0),
    count                INT NOT NULL CHECK (count > 0),
    durability           INT NOT NULL DEFAULT 0,
    max_durability       INT NOT NULL DEFAULT 0 CHECK (max_durability >= 0),
    durability_wear_raw  INT NOT NULL DEFAULT 0 CHECK (durability_wear_raw BETWEEN 0 AND 299),
    bound                BOOLEAN NOT NULL DEFAULT FALSE,
    locked               BOOLEAN NOT NULL DEFAULT FALSE,
    refine_level         INT NOT NULL DEFAULT 0 CHECK (refine_level >= 0),
    socket_count         SMALLINT NOT NULL DEFAULT 0 CHECK (socket_count BETWEEN 0 AND 5),
    sockets              INT[] NOT NULL DEFAULT ARRAY[0,0,0,0,0] CHECK (cardinality(sockets) = 5),
    wash_quality         SMALLINT NOT NULL DEFAULT 0 CHECK (wash_quality BETWEEN 0 AND 4),
    wash_count           SMALLINT NOT NULL DEFAULT 0 CHECK (wash_count BETWEEN 0 AND 4),
    wash_attrs           INT[] NOT NULL DEFAULT ARRAY[0,0,0,0] CHECK (cardinality(wash_attrs) = 4),
    wash_values          INT[] NOT NULL DEFAULT ARRAY[0,0,0,0] CHECK (cardinality(wash_values) = 4),
    wash_modes           INT[] NOT NULL DEFAULT ARRAY[0,0,0,0] CHECK (cardinality(wash_modes) = 4),
    PRIMARY KEY (mail_id, ordinal)
);

-- 普通场景死亡损失规则（单行配置，服务端读它）。客户端技能数据只证明复活
-- 技能会按比例取回经验和金钱，没有留下原服基础损失率；当前保守配置为就职
-- 等级起扣当前经验与随身金钱各 1%，获得实证后只需调整本行。
CREATE TABLE IF NOT EXISTS game_death_rule (
    id             INT PRIMARY KEY DEFAULT 1,
    min_level      INT NOT NULL DEFAULT 10 CHECK (min_level >= 0),
    exp_loss_bp    INT NOT NULL CHECK (exp_loss_bp BETWEEN 0 AND 10000),
    money_loss_bp  INT NOT NULL CHECK (money_loss_bp BETWEEN 0 AND 10000),
    CHECK (id = 1),
    CHECK (exp_loss_bp > 0 OR money_loss_bp > 0)
);
VALUES (1, 10, 100, 100)
ON CONFLICT (id) DO UPDATE
  SET min_level = 10, exp_loss_bp = 100, money_loss_bp = 100;

-- ===== folded from 0023_task_repeatable.sql =====

-- 可重复任务标记
--
-- 客户端有两份任务数据：ov_task.bin（366 行 / 337 个不同名字，建库用的）
-- 与 npc_tasks.json（717 个）。json 会在标题后缀标 `(重复)`，bin 里没有这个信息。
--
-- 曾经把这批误判成"缺失的 96 个任务"。实际上**任务本身库里都有**，
-- 缺的只是"可重复"这个标记。json 里另外那 83 个真·新任务经确认是
-- **自由幻想的内容**（我们做的是 QQ幻想），全部不要。

ALTER TABLE game_tasks ADD COLUMN IF NOT EXISTS repeatable BOOL NOT NULL DEFAULT FALSE;

-- 按 MVP 边界筛过：家族×4 / 开心辞典 / 魔神塔×9 / 试炼 都在「不做」清单里，不标。
UPDATE game_tasks SET repeatable = TRUE WHERE name IN (
    '守卫的委托：消灭甲虫',
    '守卫的委托：消灭木头人',
    '守卫的委托：消灭大蜗牛怪',
    '客栈老板的口信',
    '可恶的小黑狗',
    '矿石收购者',
    '扑蝶',
    '收购猴皮',
    '炼丹的灵药',
    '灵光之石'
);

CREATE INDEX IF NOT EXISTS idx_tasks_repeatable ON game_tasks(repeatable) WHERE repeatable;

-- ===== folded from 0024_inventory.sql =====

-- 背包持久化。
--
-- 一行一格, 不是一行一件 —— 格号本身是玩家能感知的状态(他把药放在第 3 格
-- 就该一直在第 3 格), 所以格号必须是主键的一部分。
--
-- uid 是**这一件东西**的唯一标识, 与 item_id(哪一种)不是一回事。
-- 现在只有装备用得上(每件耐久不同), 但交易/仓库/摆摊都要靠它说清"我给你的是这一件"。
-- 留到那时再加就得改表, 所以现在就带上。

CREATE TABLE IF NOT EXISTS character_items (
    char_id    BIGINT  NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
    slot       INT     NOT NULL,
    uid        BIGINT  NOT NULL DEFAULT 0,   -- 实例 id; 0 = 可堆叠物, 没有实例概念
    item_id    INT     NOT NULL,
    count      INT     NOT NULL CHECK (count > 0),
    durability INT     NOT NULL DEFAULT 0,
    max_durability INT NOT NULL DEFAULT 0 CHECK (max_durability >= 0),
    durability_wear_raw INT NOT NULL DEFAULT 0 CHECK (durability_wear_raw >= 0 AND durability_wear_raw < 300),
    PRIMARY KEY (char_id, slot)
);

-- 按角色取整包背包是最常见的查询(登录时一次)
CREATE INDEX IF NOT EXISTS idx_char_items_char ON character_items (char_id);

-- 背包格数存在角色行上: 背包类装备将来可能扩容, 那时这一列就是权威。
ALTER TABLE characters ADD COLUMN IF NOT EXISTS bag_slots INT NOT NULL DEFAULT 400;

-- 自由分配点。每级 2 点(ov_levelup.point_add), 升级时累加, 分配后扣减。
ALTER TABLE characters ADD COLUMN IF NOT EXISTS free_points INT NOT NULL DEFAULT 0;

-- 六维。此前只有 StatBlob 那个不透明块, 现在属性系统接进来了, 需要真列。
ALTER TABLE characters ADD COLUMN IF NOT EXISTS base_str INT NOT NULL DEFAULT 0;
ALTER TABLE characters ADD COLUMN IF NOT EXISTS base_vit INT NOT NULL DEFAULT 0;
ALTER TABLE characters ADD COLUMN IF NOT EXISTS base_int INT NOT NULL DEFAULT 0;
ALTER TABLE characters ADD COLUMN IF NOT EXISTS base_spi INT NOT NULL DEFAULT 0;
ALTER TABLE characters ADD COLUMN IF NOT EXISTS base_agi INT NOT NULL DEFAULT 0;
ALTER TABLE characters ADD COLUMN IF NOT EXISTS base_dex INT NOT NULL DEFAULT 0;

-- ===== folded from 0025_equipment.sql =====

-- 身上穿着的装备。
--
-- 与背包分表而不是共用 character_items: 背包按**格号**索引(玩家能感知的位置),
-- 装备按**槽位**索引(由装备自己决定, 客户端说了不算)。两者的键含义不同,
-- 混在一张表里就得靠一个 is_equipped 标志区分, 而那种标志迟早会出现
-- "既在背包里又穿在身上"的脏数据 —— 那就是刷装备漏洞。

CREATE TABLE IF NOT EXISTS character_equips (
    char_id    BIGINT NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
    slot       INT    NOT NULL,           -- game_equipment.slot
    uid        BIGINT NOT NULL DEFAULT 0, -- 实例 id
    item_id    INT    NOT NULL,
    durability INT    NOT NULL DEFAULT 0,
    max_durability INT NOT NULL DEFAULT 0 CHECK (max_durability >= 0),
    durability_wear_raw INT NOT NULL DEFAULT 0 CHECK (durability_wear_raw >= 0 AND durability_wear_raw < 300),
    PRIMARY KEY (char_id, slot)
);

CREATE INDEX IF NOT EXISTS idx_char_equips_char ON character_equips (char_id);

-- ===== folded from 0026_skills.sql =====

-- 学会的技能。
--
-- 一行一个技能。战斗技能 level 是已学等级（>0）；钓鱼/挖矿
-- 的 level 是熟练度，刚学会时可为 0。“未学习”用不存在该技能行表示。
-- 与背包/装备一样跟着角色行同事务写 —— 分开写会出现"升了级但技能没存"。

CREATE TABLE IF NOT EXISTS character_skills (
    char_id  BIGINT NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
    skill_id INT    NOT NULL,
    level    INT    NOT NULL CHECK (
        level > 0 OR (level = 0 AND skill_id IN (11006, 11007))
    ),
    PRIMARY KEY (char_id, skill_id)
);

CREATE INDEX IF NOT EXISTS idx_char_skills_char ON character_skills (char_id);

-- ===== folded from 0027_quests.sql =====

-- 任务与货币。
--
-- 货币**三种面额分开存**，不折算成统一的"铜"。
-- 理由：奖励文本里铜最大 1850、银最大 900，凑不出一个自洽的进率；
-- 硬定一个比例会把所有价格悄悄算错，而且错得没法回溯。
-- 现在只有"发奖励"这一条路径（只加不减），不需要比较大小，也就不需要进率。
-- 等接商店/交易时再去把进率查实。

ALTER TABLE characters ADD COLUMN IF NOT EXISTS money_gold   BIGINT NOT NULL DEFAULT 0;
ALTER TABLE characters ADD COLUMN IF NOT EXISTS money_silver BIGINT NOT NULL DEFAULT 0;
ALTER TABLE characters ADD COLUMN IF NOT EXISTS money_copper BIGINT NOT NULL DEFAULT 0;
ALTER TABLE characters ADD COLUMN IF NOT EXISTS honor        BIGINT NOT NULL DEFAULT 0;

-- 任务奖励的结构化结果。
--
-- 来源是 game_tasks.reward 那段**展示文本**（"雄鹰之翼；33000点经验值；5点名誉值；22银币"），
-- 奖励的结构化数值根据展示文本整理，不直接存储在客户端数据表中。
--
-- 物品是**按名字**解析出来的，且每一件都在 ov_item/ov_arm 里查到了名字才算数；
-- 查不到的一律不当物品，计入未解析，不猜。
CREATE TABLE IF NOT EXISTS game_task_rewards (
    task_id INT    PRIMARY KEY REFERENCES game_tasks(id) ON DELETE CASCADE,
    exp     BIGINT NOT NULL DEFAULT 0,
    honor   BIGINT NOT NULL DEFAULT 0,
    gold    BIGINT NOT NULL DEFAULT 0,
    silver  BIGINT NOT NULL DEFAULT 0,
    copper  BIGINT NOT NULL DEFAULT 0
);

-- 奖励物品。一行一件，按 item_id 指向 game_items / game_equipment。
CREATE TABLE IF NOT EXISTS game_task_reward_items (
    task_id INT NOT NULL REFERENCES game_tasks(id) ON DELETE CASCADE,
    seq     INT NOT NULL,
    item_id INT NOT NULL,
    qty     INT NOT NULL DEFAULT 1,
    PRIMARY KEY (task_id, seq)
);

-- 可变数量收购任务。这类任务不能压成固定 goal_qty / 固定奖励：交付时
-- 要把玩家持有的全部可收购物品按各自单价结算，再按总数选中唯一档位奖励。
CREATE TABLE IF NOT EXISTS game_task_exchange_rules (
    task_id       INT PRIMARY KEY REFERENCES game_tasks(id) ON DELETE CASCADE,
    min_total_qty INT NOT NULL CHECK (min_total_qty > 0)
);

CREATE TABLE IF NOT EXISTS game_task_exchange_items (
    task_id      INT    NOT NULL REFERENCES game_task_exchange_rules(task_id) ON DELETE CASCADE,
    ordinal      INT    NOT NULL CHECK (ordinal > 0),
    item_id      INT    NOT NULL CHECK (item_id > 0),
    item_name    TEXT   NOT NULL CHECK (item_name <> ''),
    unit_exp     BIGINT NOT NULL DEFAULT 0 CHECK (unit_exp >= 0),
    unit_honor   BIGINT NOT NULL DEFAULT 0 CHECK (unit_honor >= 0),
    unit_gold    BIGINT NOT NULL DEFAULT 0 CHECK (unit_gold >= 0),
    unit_silver  BIGINT NOT NULL DEFAULT 0 CHECK (unit_silver >= 0),
    unit_copper  BIGINT NOT NULL DEFAULT 0 CHECK (unit_copper >= 0),
    PRIMARY KEY (task_id, ordinal),
    UNIQUE (task_id, item_id)
);

CREATE TABLE IF NOT EXISTS game_task_exchange_tiers (
    task_id     INT    NOT NULL REFERENCES game_task_exchange_rules(task_id) ON DELETE CASCADE,
    min_qty     INT    NOT NULL CHECK (min_qty > 0),
    exp         BIGINT NOT NULL DEFAULT 0 CHECK (exp >= 0),
    honor       BIGINT NOT NULL DEFAULT 0 CHECK (honor >= 0),
    gold        BIGINT NOT NULL DEFAULT 0 CHECK (gold >= 0),
    silver      BIGINT NOT NULL DEFAULT 0 CHECK (silver >= 0),
    copper      BIGINT NOT NULL DEFAULT 0 CHECK (copper >= 0),
    title       TEXT   NOT NULL DEFAULT '',
    PRIMARY KEY (task_id, min_qty)
);

CREATE TABLE IF NOT EXISTS game_task_exchange_tier_items (
    task_id INT NOT NULL,
    min_qty INT NOT NULL,
    seq     INT NOT NULL CHECK (seq >= 0),
    item_id INT NOT NULL CHECK (item_id > 0),
    qty     INT NOT NULL CHECK (qty > 0),
    PRIMARY KEY (task_id, min_qty, seq),
    FOREIGN KEY (task_id, min_qty)
        REFERENCES game_task_exchange_tiers(task_id, min_qty) ON DELETE CASCADE
);

-- 角色的任务进度。
--
-- state: 0 进行中 / 1 可交付 / 2 已完成
-- 已完成的也要留着 —— 不留就没法拦住"同一个非重复任务再接一次"。
CREATE TABLE IF NOT EXISTS character_quests (
    char_id  BIGINT NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
    task_id  INT    NOT NULL,
    state    INT    NOT NULL DEFAULT 0,
    progress INT    NOT NULL DEFAULT 0,
    PRIMARY KEY (char_id, task_id)
);

CREATE INDEX IF NOT EXISTS idx_char_quests_char ON character_quests (char_id);

-- 角色已解锁称号集；characters.title 仅表示当前佩戴的称号。
CREATE TABLE IF NOT EXISTS character_titles (
    char_id     BIGINT      NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
    title       TEXT        NOT NULL CHECK (title <> ''),
    unlocked_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (char_id, title)
);

-- ===== folded from 0028_stamina_state.sql =====

-- 耐力的每日状态。
--
-- stamina_day 存的是"上次回满是哪一天"(年×1000 + 年内天序)，
-- 判据是**日期变了**而不是"过了 24 小时" —— 后者会让每天上线越来越晚的人吃亏。
ALTER TABLE characters ADD COLUMN IF NOT EXISTS stamina     INT NOT NULL DEFAULT 0;
ALTER TABLE characters ADD COLUMN IF NOT EXISTS stamina_day INT NOT NULL DEFAULT 0;
-- 特殊修理消耗念力；只按在线逻辑帧恢复，离线不补。
ALTER TABLE characters ADD COLUMN IF NOT EXISTS nianli INT NOT NULL DEFAULT 100
    CHECK (nianli >= 0 AND nianli <= 100);

-- ===== folded from 0029_work_items.sql =====

-- 打工的物品产出。
--
-- 0022 只落了经验/名誉/钱三样，**把物品漏了** —— 而物品才是打工的产出大头：
-- `ov_work_bonus_entry` 里 88 条产出条目中 81 条是物品，跨 20 个工种。
-- 最直接的后果是钓鱼（MVP 内的真工种，12~150 级）结算下来什么都不给。
--
-- 两种掷法并存，实测区分得很干净：
--
--   概率合计 = 1000   钓鱼的 10 个熟练度档，**每档都正好 1000** →「掷一次，按权重选一条鱼」
--   概率合计 ≠ 1000   贩卖物品等合计 800、杂务管理合计 1910 →「每条独立掷」
--
-- 掷法在**派生时定死**写进 roll_mode，不在运行时按合计猜 ——
-- 猜的话，将来谁调一条概率就会顺手把机制也改了，而且没人会发现。

ALTER TABLE game_work ADD COLUMN IF NOT EXISTS work_type     INT NOT NULL DEFAULT 0;
-- 挖矿/钓鱼的开工前置生活技能，来自 ov_work.skill_id；0 表示普通打工无技能要求。
ALTER TABLE game_work ADD COLUMN IF NOT EXISTS skill_id      INT NOT NULL DEFAULT 0;
-- 宠物生活辅助技能与效率增幅，来自 ov_work 的同名两列。
ALTER TABLE game_work ADD COLUMN IF NOT EXISTS pet_skill_id  INT NOT NULL DEFAULT 0;
ALTER TABLE game_work ADD COLUMN IF NOT EXISTS pet_skill_add INT NOT NULL DEFAULT 0;
-- 钓鱼靠**熟练度**分档，不是靠等级：10 档的等级段全是 12~150，
-- 区分维度是 practise_level（0 → 10000）。等级段一样的 10 行不是重复数据。
ALTER TABLE game_work ADD COLUMN IF NOT EXISTS practise_min  INT NOT NULL DEFAULT 0;
ALTER TABLE game_work ADD COLUMN IF NOT EXISTS practise_max  INT NOT NULL DEFAULT 0;
-- 0 = 每条独立掷；1 = 按权重单选
ALTER TABLE game_work ADD COLUMN IF NOT EXISTS roll_mode     INT NOT NULL DEFAULT 0;

CREATE TABLE IF NOT EXISTS game_work_items (
    work_id INT NOT NULL,
    seq     INT NOT NULL,          -- 对应 ov_work_bonus_entry.idx
    item_id INT NOT NULL,
    qty     INT NOT NULL DEFAULT 1,
    -- roll_mode=0 时是千分比；roll_mode=1 时是相对权重。
    prob    INT NOT NULL,
    -- 一次产出的熟练度随机范围是 1..practise_gain_max；0 表示不增加。
    practise_gain_max INT NOT NULL DEFAULT 0,
    PRIMARY KEY (work_id, seq)
);
CREATE INDEX IF NOT EXISTS idx_work_items_work ON game_work_items (work_id);

-- ===== folded from 0030_pets.sql =====

-- 玩家养的宠物。
--
-- 与背包/装备同一个道理：**跟角色行同事务写**，分开写会留下
-- "宠物升级存了、经验没存"的半截状态。
--
-- inst_id 是**角色内**序号，不是全局自增：宠物是角色的附属数据，
-- 与背包格子同级。用角色内序号就不需要一张全局序列表，
-- 代价是两个角色的宠会有相同的 inst_id —— 而它们从不出现在同一个句子里。

CREATE TABLE IF NOT EXISTS char_pets (
    char_id  BIGINT NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
    inst_id  BIGINT NOT NULL,          -- 角色内序号
    slot     INT    NOT NULL DEFAULT 0 CHECK (slot >= 0 AND slot < 10),
    pet_id   INT    NOT NULL,          -- 种族(ov_petgrow.pet_id, 同时也是怪物 id)
    name     TEXT   NOT NULL DEFAULT '',  -- 改过的名字; 空表示用种族名
    level    INT    NOT NULL DEFAULT 1,
    exp      BIGINT NOT NULL DEFAULT 0,

    -- 六维存**当前值**而不是由等级重算: 将来加点书/PP 果加的点不在等级里,
    -- 重算就把它们抹了
    base_str INT NOT NULL DEFAULT 0,
    base_vit INT NOT NULL DEFAULT 0,
    base_int INT NOT NULL DEFAULT 0,
    base_spi INT NOT NULL DEFAULT 0,
    base_agi INT NOT NULL DEFAULT 0,
    base_dex INT NOT NULL DEFAULT 0,

    -- 当前血/法**要存**: 与玩家不同, 宠物召回再召唤该接着上次的血,
    -- 不存的话"召回再召唤"就是免费满血
    hp INT NOT NULL DEFAULT 0,
    mp INT NOT NULL DEFAULT 0,

    trust  INT NOT NULL DEFAULT 0,
    starve INT NOT NULL DEFAULT 0,

    -- 捕捉后先是未孵化状态；prefix_id=-1 表示没有前缀（0 是“野蛮”）。
    hatched     BOOLEAN NOT NULL DEFAULT FALSE,
    gender      SMALLINT NOT NULL DEFAULT 255,
    prefix_id   INT NOT NULL DEFAULT -1,
    free_points INT NOT NULL DEFAULT 0,
    allocated_points INT NOT NULL DEFAULT 0 CHECK (allocated_points >= -1),
    active_skill INT NOT NULL DEFAULT 0,

    -- 场景实体号不落盘；只保存哪只宠正在出战，以及是否正作为坐骑使用。
    -- 重登据此重建新的宠物实体并恢复当前技能/坐骑展示。
    deployed BOOLEAN NOT NULL DEFAULT FALSE,
    riding   BOOLEAN NOT NULL DEFAULT FALSE,

    -- 领悟药丸吃下后只在下一次升级结算一次，无论成功失败都会清空。
    learn_item      INT NOT NULL DEFAULT 0,
    learn_skill     INT NOT NULL DEFAULT 0,
    learn_chance_bp INT NOT NULL DEFAULT 0,

    PRIMARY KEY (char_id, inst_id),
    CONSTRAINT char_pets_riding_requires_deployed CHECK (NOT riding OR deployed),
    CONSTRAINT char_pets_gender_after_hatch CHECK (
        (hatched AND gender IN (0, 1)) OR (NOT hatched AND gender = 255))
);

-- Existing development databases predate persistent pet-book ordering. Backfill only characters
-- whose slots are duplicated or outside the official ten-slot range; valid player ordering is
-- never rewritten when init is re-applied.
ALTER TABLE char_pets ADD COLUMN IF NOT EXISTS slot INT NOT NULL DEFAULT 0;
WITH invalid_chars AS (
    SELECT char_id
      FROM char_pets
     GROUP BY char_id
    HAVING COUNT(*) <> COUNT(DISTINCT slot)
        OR MIN(slot) < 0 OR MAX(slot) >= 10
), ranked AS (
    SELECT p.char_id, p.inst_id,
           ROW_NUMBER() OVER (PARTITION BY p.char_id ORDER BY p.inst_id) - 1 AS next_slot
      FROM char_pets p
      JOIN invalid_chars i ON i.char_id = p.char_id
)
UPDATE char_pets p
   SET slot = r.next_slot
  FROM ranked r
 WHERE p.char_id = r.char_id AND p.inst_id = r.inst_id;

CREATE INDEX IF NOT EXISTS idx_char_pets_char ON char_pets (char_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_char_pets_slot ON char_pets (char_id, slot);
CREATE UNIQUE INDEX IF NOT EXISTS uq_char_pets_one_deployed
    ON char_pets (char_id) WHERE deployed;

-- 宠物已学技能。技能效果不在本表；这里只保存领悟、等级和当前启用项。
CREATE TABLE IF NOT EXISTS char_pet_skills (
    char_id BIGINT NOT NULL,
    inst_id BIGINT NOT NULL,
    skill_id INT NOT NULL,
    level INT NOT NULL DEFAULT 1 CHECK (level > 0),
    PRIMARY KEY (char_id, inst_id, skill_id),
    FOREIGN KEY (char_id, inst_id) REFERENCES char_pets(char_id, inst_id) ON DELETE CASCADE
);

-- 粉粉兔 pets.json 的逐种族宠物配置。运行时只读 PostgreSQL，不读取 JSON。
-- model_id 不是 pet_id：海龟分别是 206 与 1006，混用会显示成人偶。
-- ov_petgrow.eats1_id 是食物物品，不是协议食性枚举。万般香为客户端“杂食”。
CREATE TABLE IF NOT EXISTS game_pet_food_habits (
    food_item_id INT PRIMARY KEY,
    habit SMALLINT NOT NULL CHECK (habit BETWEEN 1 AND 4)
);
ON CONFLICT (food_item_id) DO UPDATE SET habit = EXCLUDED.habit;

CREATE TABLE IF NOT EXISTS game_pet_profiles (
    pet_id INT PRIMARY KEY,
    model_id INT NOT NULL CHECK (model_id > 0),
    blessing_slots INT NOT NULL CHECK (blessing_slots >= 0),
    initial_skill_names TEXT[] NOT NULL DEFAULT '{}',
    forbidden_skill_names TEXT[] NOT NULL DEFAULT '{}'
);

