-- 宠物技能的主动/被动语义。ov_skilldesc.is_combat 是“战斗中可用”，
-- 不是客户端 PetSkill.active；二者决定技能能否拖入快捷栏并主动使用。
CREATE TABLE IF NOT EXISTS game_pet_skill_profiles (
    skill_id INT PRIMARY KEY CHECK (skill_id > 0),
    active BOOLEAN NOT NULL
);

ON CONFLICT (skill_id) DO UPDATE SET active = EXCLUDED.active;


-- 宠物天赋与交互规则的最终业务配置。
CREATE TABLE game_pet_skill_effects (
 skill_id INT PRIMARY KEY REFERENCES game_pet_skill_profiles(skill_id),
 kind TEXT NOT NULL,
 chance_bp INT NOT NULL DEFAULT 10000 CHECK(chance_bp BETWEEN 0 AND 10000),
 chance_per_level_bp INT NOT NULL DEFAULT 0 CHECK(chance_per_level_bp>=0),
 value INT NOT NULL DEFAULT 0 CHECK(value>=0),
 value_per_level INT NOT NULL DEFAULT 0 CHECK(value_per_level>=0),
 source_attr INT NOT NULL DEFAULT 0,
 source_step INT NOT NULL DEFAULT 1 CHECK(source_step>0),
 require_selected BOOLEAN NOT NULL DEFAULT FALSE
);
