CREATE TABLE game_item_pet_eggs (
 item_id INT PRIMARY KEY REFERENCES game_items(id),
 pet_id INT NOT NULL REFERENCES game_pet_profiles(pet_id),
 name TEXT NOT NULL DEFAULT '',
 description TEXT NOT NULL DEFAULT ''
);
CREATE TABLE game_pickup_rule (
 id SMALLINT PRIMARY KEY CHECK(id=1),
 pickup_range INT NOT NULL CHECK(pickup_range>0)
);
CREATE TABLE game_refine_policy (
 id SMALLINT PRIMARY KEY CHECK(id=1),
 destroy_from_level INT NOT NULL CHECK(destroy_from_level>=0),
 confirm_cooldown_ms INT NOT NULL CHECK(confirm_cooldown_ms>0)
);

-- 名字只用于忠实保存 pets.json；运行时通过 ov_skilldesc 的权威技能号使用。
-- pets.json 的“不学技能”是黑名单。它发布后新增的驱毒/阳春等技能不在旧列表中，
-- 因此按官方规则可在达到技能等级门槛后领悟。
CREATE OR REPLACE VIEW game_pet_initial_skills AS
WITH pet_skills AS (
    SELECT DISTINCT ON (skill_id) skill_id, name
      FROM gamedata.ov_skilldesc
     WHERE skill_level = 1 AND max_level_pet > 0
     ORDER BY skill_id, row_no
)
SELECT p.pet_id, s.skill_id
  FROM game_pet_profiles p
 CROSS JOIN LATERAL unnest(p.initial_skill_names) AS n(name)
  JOIN pet_skills s ON s.name = n.name;

CREATE OR REPLACE VIEW game_pet_learnable_skills AS
WITH pet_skills AS (
    SELECT DISTINCT ON (skill_id) skill_id, name
      FROM gamedata.ov_skilldesc
     WHERE skill_level = 1 AND max_level_pet > 0
     ORDER BY skill_id, row_no
)
SELECT p.pet_id, s.skill_id
  FROM game_pet_profiles p
 CROSS JOIN pet_skills s
 WHERE NOT (s.name = ANY (p.forbidden_skill_names));

-- 用户确认的宠物规则；未由客户端表给出的概率也放在数据库，便于后续平衡。
CREATE TABLE IF NOT EXISTS game_pet_rule (
    max_life_skills INT NOT NULL DEFAULT 8 CHECK(max_life_skills BETWEEN 1 AND 8),
    max_fight_skills INT NOT NULL DEFAULT 4 CHECK(max_fight_skills BETWEEN 1 AND 4),
    id SMALLINT PRIMARY KEY CHECK (id = 1),
    natural_learn_chance_bp INT NOT NULL CHECK (natural_learn_chance_bp BETWEEN 0 AND 10000),
    initial_skill_min INT NOT NULL CHECK (initial_skill_min >= 0),
    initial_skill_max INT NOT NULL CHECK (initial_skill_max >= initial_skill_min),
    low_trust_refuse_bp INT NOT NULL CHECK (low_trust_refuse_bp BETWEEN 0 AND 10000),
    zero_trust_recall_sec INT NOT NULL DEFAULT 10 CHECK (zero_trust_recall_sec > 0),
    hunger_interval_sec INT NOT NULL CHECK (hunger_interval_sec > 0),
    trust_happy_sec INT NOT NULL CHECK (trust_happy_sec > 0),
    trust_content_sec INT NOT NULL CHECK (trust_content_sec > 0),
    deploy_hunger_add INT NOT NULL CHECK (deploy_hunger_add >= 0),
    death_trust_loss INT NOT NULL CHECK (death_trust_loss >= 0),
    trade_trust_required INT NOT NULL CHECK (trade_trust_required >= 0),
    trade_trust_loss INT NOT NULL CHECK (trade_trust_loss >= 0)
);

    id, max_life_skills, max_fight_skills, natural_learn_chance_bp, initial_skill_min, initial_skill_max,
    low_trust_refuse_bp, zero_trust_recall_sec, hunger_interval_sec, trust_happy_sec, trust_content_sec,
    deploy_hunger_add, death_trust_loss, trade_trust_required, trade_trust_loss
) VALUES (1, 8, 4, 2000, 0, 0, 2000, 10, 300, 60, 120, 1, 10, 50, 50)
ON CONFLICT (id) DO UPDATE SET
    max_life_skills = EXCLUDED.max_life_skills,
    max_fight_skills = EXCLUDED.max_fight_skills,
    natural_learn_chance_bp = EXCLUDED.natural_learn_chance_bp,
    initial_skill_min = EXCLUDED.initial_skill_min,
    initial_skill_max = EXCLUDED.initial_skill_max,
    low_trust_refuse_bp = EXCLUDED.low_trust_refuse_bp,
    zero_trust_recall_sec = EXCLUDED.zero_trust_recall_sec,
    hunger_interval_sec = EXCLUDED.hunger_interval_sec,
    trust_happy_sec = EXCLUDED.trust_happy_sec,
    trust_content_sec = EXCLUDED.trust_content_sec,
    deploy_hunger_add = EXCLUDED.deploy_hunger_add,
    death_trust_loss = EXCLUDED.death_trust_loss,
    trade_trust_required = EXCLUDED.trade_trust_required,
    trade_trust_loss = EXCLUDED.trade_trust_loss;

-- 官方道具说明明确写出的“下一次升级领悟”技能与概率（万分比）。
CREATE TABLE IF NOT EXISTS game_pet_learning_items (
    item_id INT PRIMARY KEY,
    skill_id INT NOT NULL,
    chance_bp INT NOT NULL CHECK (chance_bp BETWEEN 1 AND 10000)
);

ON CONFLICT (item_id) DO UPDATE SET
    skill_id = EXCLUDED.skill_id,
    chance_bp = EXCLUDED.chance_bp;

-- ===== folded from 0031_friends.sql =====

-- 好友。
--
-- **双向存两行。** 甲加乙为好友时，(甲,乙) 和 (乙,甲) 各写一行。
--
-- 存单向的话，"我上线时通知我的好友们"就得反查「谁把我加成了好友」——
-- 那是一次全表扫描，而且随在线人数增长。存双向之后这件事退化成
-- 「遍历我自己的列表」，代价是加/删好友要写两行（而那是人类速度的操作）。
--
-- 冗余带来的一致性风险由**同事务写两行**兜住：要么都成要么都不成。

CREATE TABLE IF NOT EXISTS char_friends (
    char_id    BIGINT NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
    friend_id  BIGINT NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
    -- remark 备注名。玩家给好友起的名字，空表示用角色名。
    remark     TEXT   NOT NULL DEFAULT '',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    PRIMARY KEY (char_id, friend_id),
    -- 不能加自己。数据库这一层挡住，比在代码里挡可靠 ——
    -- 代码路径会变多，约束只有一条
    CHECK (char_id <> friend_id)
);

-- 查"我的好友有谁"是最热的操作(每次登录一次)
CREATE INDEX IF NOT EXISTS idx_char_friends_char ON char_friends (char_id);

-- 1.5.8 单向屏蔽名单。scope 保留客户端上报的 0/1 原值；
-- 服务端对两种值都执行消息和交互拦截，不把未证明的 UI 细分硬编进数据库。
CREATE TABLE IF NOT EXISTS char_blocks (
    char_id         BIGINT   NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
    blocked_char_id BIGINT   NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
    scope           SMALLINT NOT NULL DEFAULT 0 CHECK (scope IN (0, 1)),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    PRIMARY KEY (char_id, blocked_char_id),
    CHECK (char_id <> blocked_char_id)
);

CREATE INDEX IF NOT EXISTS idx_char_blocks_blocked ON char_blocks (blocked_char_id);

-- ===== folded from 0032_char_attrs.sql =====

-- 把 stat_blob 那个不透明块拆成真列。
--
-- stat_blob 是 166 字节的旧角色属性块。角色列表要求该块长度固定；其字段结构为:
--
--   [0..11]  外观装备 6 个 u16   → 已经有 equip_view 列了
--   [12]     atkVariant  u8
--   [13]     weaponCType u8
--   [14..15] atkDist     u16
--   [16..17] 属性个数    u16
--   [18..]   属性数组    int32 × 个数
--   末尾 8B  honor       i64      → 已经有 honor 列了
--
-- 所以这里只需要补 atk_* 三列和 attrs, 然后把块本身删掉。

ALTER TABLE characters ADD COLUMN IF NOT EXISTS atk_variant  SMALLINT   NOT NULL DEFAULT 0;
ALTER TABLE characters ADD COLUMN IF NOT EXISTS weapon_ctype SMALLINT   NOT NULL DEFAULT 0;
ALTER TABLE characters ADD COLUMN IF NOT EXISTS atk_dist     INT        NOT NULL DEFAULT 0;
ALTER TABLE characters ADD COLUMN IF NOT EXISTS attrs        INT[]      NOT NULL DEFAULT '{}';

-- 回填旧角色数据中的属性；不丢弃已有值。
-- 新迁移器第一次接管旧库时会从 0001 重放并登记校验和；旧库可能已经执行过
-- 本迁移且删掉了 stat_blob，因此只有该列仍存在时才读取。分支内语句在条件为假
-- 时不会被规划，也就不会因列已不存在而阻断接管。
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
          FROM information_schema.columns
         WHERE table_schema = 'public'
           AND table_name = 'characters'
           AND column_name = 'stat_blob'
    ) THEN
        UPDATE characters SET
            atk_variant  = get_byte(stat_blob, 12),
            weapon_ctype = get_byte(stat_blob, 13),
            atk_dist     = get_byte(stat_blob, 14) + get_byte(stat_blob, 15) * 256
        WHERE octet_length(stat_blob) >= 16;

        UPDATE characters c SET attrs = COALESCE((
            SELECT array_agg(
                       get_byte(c.stat_blob, 18 + i * 4)
                     + get_byte(c.stat_blob, 19 + i * 4) * 256
                     + get_byte(c.stat_blob, 20 + i * 4) * 65536
                     -- 第 4 字节按有符号解: 属性值不会是天文数字, 高位置 1 只可能是负数
                     + CASE WHEN get_byte(c.stat_blob, 21 + i * 4) >= 128
                            THEN (get_byte(c.stat_blob, 21 + i * 4) - 256) * 16777216
                            ELSE  get_byte(c.stat_blob, 21 + i * 4)        * 16777216 END
                     ORDER BY i)
            FROM generate_series(0,
                     get_byte(c.stat_blob, 16) + get_byte(c.stat_blob, 17) * 256 - 1) AS i
            -- 数组必须完整装得下, 否则 get_byte 会越界报错
            WHERE octet_length(c.stat_blob)
                  >= 18 + (get_byte(c.stat_blob, 16) + get_byte(c.stat_blob, 17) * 256) * 4
        ), '{}')
        WHERE octet_length(c.stat_blob) >= 18;
    END IF;
END $$;

ALTER TABLE characters DROP COLUMN IF EXISTS stat_blob;

-- ===== folded from 0033_item_bound.sql =====

-- 物品实例的永久绑定状态。
--
-- 真实 0x8006 在背包项中下发 bound U8。未绑定普通装备穿戴前，
-- 客户端明确提示“装备后将绑定”；原服成功穿戴后的装备描述也出现
-- “（绑定）/绑定物品不可交易”。所以这不能是只存在客户端的临时状态。

ALTER TABLE character_items
    ADD COLUMN IF NOT EXISTS bound BOOLEAN NOT NULL DEFAULT FALSE;

ALTER TABLE character_equips
    ADD COLUMN IF NOT EXISTS bound BOOLEAN NOT NULL DEFAULT FALSE;

-- 玩家主动设置的物品保护。它与绑定状态独立；FALSE 是未设置保护的显式哨兵。
ALTER TABLE character_items
    ADD COLUMN IF NOT EXISTS locked BOOLEAN NOT NULL DEFAULT FALSE;

ALTER TABLE character_equips
    ADD COLUMN IF NOT EXISTS locked BOOLEAN NOT NULL DEFAULT FALSE;

ALTER TABLE character_items
    ADD COLUMN IF NOT EXISTS refine_level INT NOT NULL DEFAULT 0 CHECK (refine_level >= 0);

ALTER TABLE character_equips
    ADD COLUMN IF NOT EXISTS refine_level INT NOT NULL DEFAULT 0 CHECK (refine_level >= 0);

ALTER TABLE character_items
    ADD COLUMN IF NOT EXISTS socket_count SMALLINT NOT NULL DEFAULT 0 CHECK (socket_count BETWEEN 0 AND 5),
    ADD COLUMN IF NOT EXISTS sockets INT[] NOT NULL DEFAULT ARRAY[0,0,0,0,0]
        CHECK (cardinality(sockets) = 5);

ALTER TABLE character_equips
    ADD COLUMN IF NOT EXISTS socket_count SMALLINT NOT NULL DEFAULT 0 CHECK (socket_count BETWEEN 0 AND 5),
    ADD COLUMN IF NOT EXISTS sockets INT[] NOT NULL DEFAULT ARRAY[0,0,0,0,0]
        CHECK (cardinality(sockets) = 5);

ALTER TABLE character_items
    ADD COLUMN IF NOT EXISTS wash_quality SMALLINT NOT NULL DEFAULT 0 CHECK (wash_quality BETWEEN 0 AND 4),
    ADD COLUMN IF NOT EXISTS wash_count SMALLINT NOT NULL DEFAULT 0 CHECK (wash_count BETWEEN 0 AND 4),
    ADD COLUMN IF NOT EXISTS wash_attrs INT[] NOT NULL DEFAULT ARRAY[0,0,0,0] CHECK (cardinality(wash_attrs) = 4),
    ADD COLUMN IF NOT EXISTS wash_values INT[] NOT NULL DEFAULT ARRAY[0,0,0,0] CHECK (cardinality(wash_values) = 4),
    ADD COLUMN IF NOT EXISTS wash_modes INT[] NOT NULL DEFAULT ARRAY[0,0,0,0] CHECK (cardinality(wash_modes) = 4);

ALTER TABLE character_equips
    ADD COLUMN IF NOT EXISTS wash_quality SMALLINT NOT NULL DEFAULT 0 CHECK (wash_quality BETWEEN 0 AND 4),
    ADD COLUMN IF NOT EXISTS wash_count SMALLINT NOT NULL DEFAULT 0 CHECK (wash_count BETWEEN 0 AND 4),
    ADD COLUMN IF NOT EXISTS wash_attrs INT[] NOT NULL DEFAULT ARRAY[0,0,0,0] CHECK (cardinality(wash_attrs) = 4),
    ADD COLUMN IF NOT EXISTS wash_values INT[] NOT NULL DEFAULT ARRAY[0,0,0,0] CHECK (cardinality(wash_values) = 4),
    ADD COLUMN IF NOT EXISTS wash_modes INT[] NOT NULL DEFAULT ARRAY[0,0,0,0] CHECK (cardinality(wash_modes) = 4);

-- 已穿在身上的普通装备必然经历过绑定；NetClient.IsMiningTool 中精确
-- 特判的 0x76d/0x3aba 除外。这条校正故意每次重放：若迁移时旧服务还在线，
-- 它的关服快照不认识新字段，会在首次回填后把 bound 重新写成 false。
-- 幂等 UPDATE 使得旧进程完全停止后重放迁移仍能修复这个升级时序。
UPDATE character_equips
   SET bound = TRUE
 WHERE item_id NOT IN (1901, 15034)
   AND bound = FALSE;

-- ===== 个人仓库 =====
-- 用户确认：仓库按角色独立；初始 3 页，每页 100 格；仓库堆叠上限默认 999。
-- dir/mode 的数值方向由 PostgreSQL 配置控制，便于按实际规则调整。
CREATE TABLE IF NOT EXISTS game_warehouse_rule (
    singleton          BOOLEAN  PRIMARY KEY DEFAULT TRUE CHECK (singleton),
    initial_pages      SMALLINT NOT NULL DEFAULT 3   CHECK (initial_pages BETWEEN 1 AND 255),
    slots_per_page     SMALLINT NOT NULL DEFAULT 100 CHECK (slots_per_page > 0),
    max_stack          INT      NOT NULL DEFAULT 999 CHECK (max_stack > 0),
    move_deposit_dir   SMALLINT NOT NULL DEFAULT 0   CHECK (move_deposit_dir BETWEEN 0 AND 1),
    money_deposit_mode SMALLINT NOT NULL DEFAULT 0   CHECK (money_deposit_mode BETWEEN 0 AND 1)
);
ON CONFLICT (singleton) DO NOTHING;

CREATE TABLE IF NOT EXISTS character_warehouses (
    char_id     BIGINT   PRIMARY KEY REFERENCES characters(id) ON DELETE CASCADE,
    page_count  SMALLINT NOT NULL DEFAULT 3 CHECK (page_count BETWEEN 1 AND 255),
    money       BIGINT   NOT NULL DEFAULT 0 CHECK (money >= 0)
);

CREATE TABLE IF NOT EXISTS character_warehouse_items (
    char_id               BIGINT   NOT NULL REFERENCES characters(id) ON DELETE CASCADE,
    page                  SMALLINT NOT NULL CHECK (page BETWEEN 0 AND 254),
    slot                  INT      NOT NULL CHECK (slot >= 0),
    uid                   BIGINT   NOT NULL DEFAULT 0,
    item_id               INT      NOT NULL,
    count                 INT      NOT NULL CHECK (count > 0),
    durability            INT      NOT NULL DEFAULT 0,
    max_durability        INT      NOT NULL DEFAULT 0 CHECK (max_durability >= 0),
    durability_wear_raw   INT      NOT NULL DEFAULT 0 CHECK (durability_wear_raw >= 0 AND durability_wear_raw < 300),
    bound                 BOOLEAN  NOT NULL DEFAULT FALSE,
    locked                BOOLEAN  NOT NULL DEFAULT FALSE,
    refine_level          INT      NOT NULL DEFAULT 0 CHECK (refine_level >= 0),
    socket_count          SMALLINT NOT NULL DEFAULT 0 CHECK (socket_count BETWEEN 0 AND 5),
    sockets               INT[]    NOT NULL DEFAULT ARRAY[0,0,0,0,0] CHECK (cardinality(sockets) = 5),
    wash_quality          SMALLINT NOT NULL DEFAULT 0 CHECK (wash_quality BETWEEN 0 AND 4),
    wash_count            SMALLINT NOT NULL DEFAULT 0 CHECK (wash_count BETWEEN 0 AND 4),
    wash_attrs            INT[]    NOT NULL DEFAULT ARRAY[0,0,0,0] CHECK (cardinality(wash_attrs) = 4),
    wash_values           INT[]    NOT NULL DEFAULT ARRAY[0,0,0,0] CHECK (cardinality(wash_values) = 4),
    wash_modes            INT[]    NOT NULL DEFAULT ARRAY[0,0,0,0] CHECK (cardinality(wash_modes) = 4),
    PRIMARY KEY (char_id, page, slot)
);
CREATE INDEX IF NOT EXISTS idx_char_warehouse_items_char
    ON character_warehouse_items(char_id);

