ALTER TABLE characters ADD COLUMN IF NOT EXISTS pet_view_mask       INT      NOT NULL DEFAULT 0;
ALTER TABLE characters ADD COLUMN IF NOT EXISTS hotbar_ids          INT[]    NOT NULL DEFAULT '{}';
ALTER TABLE characters ADD COLUMN IF NOT EXISTS hotbar_kinds        BYTEA    NOT NULL DEFAULT '\x';
ALTER TABLE characters ADD COLUMN IF NOT EXISTS hotbar_expanded     BOOLEAN  NOT NULL DEFAULT FALSE;
