    CHECK (pk_mode BETWEEN 0 AND 4);
-- 状态实例快照是运行态存档，不是服务端业务配置；每项保留实际来源覆盖后的定义。
ALTER TABLE characters ADD COLUMN IF NOT EXISTS saved_statuses JSONB NOT NULL DEFAULT '[]'::jsonb
    CHECK (jsonb_typeof(saved_statuses) = 'array');
