ALTER TABLE characters ADD COLUMN IF NOT EXISTS exp_bonus_remaining_ticks BIGINT NOT NULL DEFAULT 0 CHECK (exp_bonus_remaining_ticks >= 0);
ALTER TABLE characters ADD COLUMN IF NOT EXISTS pet_exp_bonus_pct INT NOT NULL DEFAULT 0 CHECK (pet_exp_bonus_pct >= 0);
ALTER TABLE characters ADD COLUMN IF NOT EXISTS pet_exp_bonus_remaining_ticks BIGINT NOT NULL DEFAULT 0 CHECK (pet_exp_bonus_remaining_ticks >= 0);

-- 旧库里已经佩戴的称号必然也属于该角色，先纳入已解锁集。
SELECT id, title FROM characters WHERE title <> ''
ON CONFLICT (char_id, title) DO NOTHING;

-- 旧实现升级技能不扣点。迁移时按“每次升级 1 点、每个已学等级花 1 点”补齐
-- 当前余额；以后所有增减都直接维护 skill_points，不再重算。
UPDATE characters c
   SET skill_points = GREATEST(c.level - 1 - COALESCE((
       SELECT SUM(s.level) FROM character_skills s WHERE s.char_id = c.id
   ), 0), 0)
 WHERE c.skill_points = 0;

-- ===== folded from 0035_task_prerequisites.sql =====

-- 任务前置链。ov_task.PreTask 是 5 个有序任务号槽，0 表示空槽。
-- 当前原始数据中 168 个任务有前置，其中 3 个使用了第 2~5 槽；
-- 不能简化成单个 prerequisite_id。
CREATE TABLE IF NOT EXISTS game_task_prerequisites (
    task_id              INT      NOT NULL REFERENCES game_tasks(id) ON DELETE CASCADE,
    seq                  SMALLINT NOT NULL CHECK (seq BETWEEN 1 AND 5),
    prerequisite_task_id INT      NOT NULL REFERENCES game_tasks(id) ON DELETE RESTRICT,
    PRIMARY KEY (task_id, seq),
    UNIQUE (task_id, prerequisite_task_id)
);

CREATE INDEX IF NOT EXISTS idx_task_prerequisites_required
    ON game_task_prerequisites(prerequisite_task_id);

-- ===== folded from 0036_character_employment.sql =====

-- race 保存建角时选定的未来职业路线；客户端当前身份在未就职时仍是初行者。
