-- 存量角色沿用历史行为视为已就职，新建角色由应用显式写入 false。
ALTER TABLE characters ADD COLUMN IF NOT EXISTS employed BOOLEAN;

UPDATE characters SET employed = TRUE WHERE employed IS NULL;

ALTER TABLE characters ALTER COLUMN employed SET DEFAULT FALSE;
ALTER TABLE characters ALTER COLUMN employed SET NOT NULL;

