WITH airship_hubs(sort_order, trans_list, map_id, name, x, y) AS (VALUES
  (1, 14, 61, '桃源东村', 5051, 997),
  (2, 4, 37, '桃源西村', 6050, 686),
  (3, 15, 62, '长乐东村', 9888, 5363),
  (4, 5, 38, '长乐西村', 9888, 5363),
  (5, 1, 7, '龙城', 9475, 7395),
  (6, 3, 19, '出云城', 3051, 4208),
  (7, 2, 32, '天都', 13717, 2548),
  (8, 13, 58, '楼兰城', 5656, 4685),
  (9, 17, 86, '无泪城', 2383, 3615),
  (10, 20, 143, '云荒部落', 5714, 3834),
  (11, 25, 154, '比翼城', 6435, 1865)
), routes AS (
  SELECT src.trans_list,
         (row_number() OVER (PARTITION BY src.trans_list ORDER BY dst.sort_order) - 1)::INT AS destination_index,
         src.map_id AS source_map_id,
         dst.name, dst.map_id, dst.x, dst.y, 0 AS price
    FROM airship_hubs src
    JOIN airship_hubs dst
      ON dst.trans_list <> src.trans_list
     AND dst.map_id NOT IN (86, 143, 154)
)
SELECT trans_list, destination_index, source_map_id, name, map_id, x, y, price
  FROM routes
ON CONFLICT (trans_list, destination_index) DO UPDATE SET
  source_map_id = EXCLUDED.source_map_id,
  name = EXCLUDED.name,
  map_id = EXCLUDED.map_id,
  x = EXCLUDED.x,
  y = EXCLUDED.y,
  price = EXCLUDED.price;

-- 第一版七个副本、十一张地图。MaxInst 在原始 pworld.def 中未配置，0 由
-- 领域层翻译为 DefaultMaxInstances；其它数值逐项保留原文件和门的真值。
ON CONFLICT (map_id) DO UPDATE SET
  dungeon_id = EXCLUDED.dungeon_id,
  name = EXCLUDED.name,
  enter_x = EXCLUDED.enter_x,
  enter_y = EXCLUDED.enter_y,
  exit_map_id = EXCLUDED.exit_map_id,
  exit_x = EXCLUDED.exit_x,
  exit_y = EXCLUDED.exit_y,
  timeout_sec = EXCLUDED.timeout_sec,
  max_instances = EXCLUDED.max_instances;

