  FROM portraits p
 WHERE n.name = p.name AND n.sprite = p.sprite AND n.script = p.script;

-- 客户端没有独立的“进入副本”上行方法。使用已经闭合的 NPC TransportUI：
-- 0x8046 下发列表号，0x1071 打开菜单，0x1072 回传选择。is_dungeon 只由
-- 服务端数据库决定，选中后进入队伍专属实例而非普通常驻图。
ON CONFLICT (trans_list, destination_index) DO UPDATE SET
  source_map_id = EXCLUDED.source_map_id,
  name = EXCLUDED.name,
  map_id = EXCLUDED.map_id,
  x = EXCLUDED.x,
  y = EXCLUDED.y,
  price = EXCLUDED.price,
  is_dungeon = EXCLUDED.is_dungeon,
  require_clear = EXCLUDED.require_clear;

-- 失落神殿古代石碑：二层直接进入三层，不要求清场；三层可选择离开副本。
-- 出本落点与失落神殿副本定义一致，三层原始 link 门仍负责返回二层。
ON CONFLICT (trans_list, destination_index) DO UPDATE SET
  source_map_id = EXCLUDED.source_map_id,
  name = EXCLUDED.name,
  map_id = EXCLUDED.map_id,
  x = EXCLUDED.x,
  y = EXCLUDED.y,
  price = EXCLUDED.price,
  is_dungeon = EXCLUDED.is_dungeon,
  require_clear = EXCLUDED.require_clear;

