   SET trans_list = 109
 WHERE map_file = 'pw20902'
   AND name = '古代石碑'
   AND script = 'N974LL_5';

UPDATE map_npcs
   SET trans_list = 133
 WHERE map_file = 'pw20903'
   AND name = '古代石碑'
   AND script = 'N974LL_6';

WITH entrances(map_file, npc_name, trans_list) AS (VALUES
  ('qw0037', '病叟', 101),
  ('qw0061', '病叟', 102),
  ('qw0038', '寂仙子', 103),
  ('qw0062', '寂仙子', 104),
  ('qw0004', '墨玉', 105),
  ('qw0019', '纯阳塔神卫', 106),
  ('qw0032', '二郎神杨戬', 107),
  ('qw0081', '斯芬尼克', 108)
)
UPDATE map_npcs AS npc
   SET trans_list = entrance.trans_list
  FROM entrances AS entrance
 WHERE npc.map_file = entrance.map_file
   AND npc.name = entrance.npc_name;

DO $$
BEGIN
  IF (SELECT count(*) FROM map_npcs WHERE trans_list BETWEEN 101 AND 108) <> 8 THEN
    RAISE EXCEPTION '第一版副本入口 NPC 未精确绑定 8 行';
  END IF;
END $$;
-- 对话与多层地图的副本归属。来源：客户端 pworld.def、map.def、.link
-- 与 dungeon_entrances.json；单人模式来自任务 355/356/359/361 的明确文字。
-- 家族屋、幻想小岛不纳入；尚未开放的争霸三图与 41500 不配置入口。
ON CONFLICT (map_id) DO UPDATE SET
  dungeon_id = EXCLUDED.dungeon_id,
  name = EXCLUDED.name,
  enter_x = EXCLUDED.enter_x,
  enter_y = EXCLUDED.enter_y,
  exit_map_id = EXCLUDED.exit_map_id,
  exit_x = EXCLUDED.exit_x,
  exit_y = EXCLUDED.exit_y,
  timeout_sec = EXCLUDED.timeout_sec,
  max_instances = EXCLUDED.max_instances,
  solo = EXCLUDED.solo;

