  source_map_id = EXCLUDED.source_map_id,
  name = EXCLUDED.name,
  map_id = EXCLUDED.map_id,
  x = EXCLUDED.x,
  y = EXCLUDED.y,
  price = EXCLUDED.price,
  is_dungeon = EXCLUDED.is_dungeon;

