WITH field_transport_hubs(sort_order, trans_list, map_id, name, x, y) AS (VALUES
  (1, 6, 4, '华山脚', 5446, 2797),
  (2, 7, 21, '下古岳平原', 9201, 1953),
  (3, 8, 36, '瑶池台', 8986, 2532),
  (4, 9, 33, '上天郊', 9106, 1989),
  (5, 10, 15, '青牛山脚', 4722, 2719),
  (6, 11, 18, '大秦山原东', 8125, 1561),
  (7, 12, 55, '蚂蚁沙地', 5900, 3882)
), routes AS (
  SELECT src.trans_list,
         (row_number() OVER (PARTITION BY src.trans_list ORDER BY dst.sort_order) - 1)::INT AS destination_index,
         src.map_id AS source_map_id,
         dst.name, dst.map_id, dst.x, dst.y, 0 AS price
    FROM field_transport_hubs src
    JOIN field_transport_hubs dst ON dst.trans_list <> src.trans_list
)
